题目 综述 寻找有序序列中第一个满足某条件的元素的位置：以下代码为这种类型二分模板 对应于本题，以下代码实现：找到第一个满足nums[i]&gt;i的下标 class Solution &#123;public: int missingNumber(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); int low=0; int high=n;//注意1，查找区间左闭右开 int mid; while(low&lt;high)&#123;//注意2 mid=(low+high)/2; if(nums[mid]&gt;mid)high=mid;//注意3，寻找第一个满足条件的下标 else low=mid+1; &#125; return low;//注意4，low和left均可 &#125;&#125;;
寻找有序序列中最后一个满足某条件的元素的位置（返回值需要-1）：以下代码为这种类型二分模板，注意和上述代码中low,high位置区别 本题变形：找到最后一个nums[i]&#x3D;&#x3D;i的下标，代码如下 class Solution &#123;public: int missingNumber(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); int low=0; int high=n;//注意1，查找区间左闭右开 int mid; while(low&lt;high)&#123;//注意2 mid=(low+high)/2; if(nums[mid]==mid)low=mid+1;//注意3，寻找最后一个满足条件的下标 else high=mid; &#125; return low-1;//注意4，low和left均可，此时需要减一 &#125;&#125;;
寻找有序序列中满足某条件的元素的位置（防止mid溢出的方法）：以下代码为这种类型二分模板 int binarySearch(int A[],int left,int right,int x)&#123; int mid; while(left&lt;=right)&#123; mid=(left+right)/2;//mid=left+(right-left)/2;防止mid溢出 if(A[mid]==x)return mid; else if(A[mid]&gt;x)right=mid-1; else left=mid+1; &#125; return -1;&#125;
复杂度分析

题目 综述https://leetcode-cn.com/problems/next-permutation/solution/xia-yi-ge-pai-lie-suan-fa-xiang-jie-si-lu-tui-dao-/] # 调用STL的函数 void nextPermutation(vector&lt;int&gt;&amp; nums) &#123; next_permutation(nums.begin(),nums.end()); // STL功能和题目描述一致 &#125;
# 手动实现 时间复杂度O(n),空间复杂度O(1)
从后往前找到第一个【相邻升序对】，即A[i]&lt;A[i+1]。此时A[i+1,end)为降序。 在区间[i+1,end)中，从后往前找到第一个大于A[i]的元素A[j] 交换A[i]和A[j]，此时A[i+1,end)一定还是降序，因为A[j]是从右侧起第一个大于A[i]的值 反转A[i+1,end)，变成升序
应用场景：可兼容处理含有重复元素的全排列问题 Codeclass Solution &#123;public: void nextPermutation(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); if(n&lt;2)return; int i,j; for(i=n-2;i&gt;=0;i--)&#123; if(nums[i]&lt;nums[i+1])&#123; break; &#125; &#125; if(i==-1)&#123; reverse(nums.begin(),nums.end());//原数组为降序序列，此时反转即可 return; &#125; for(j=n-1;j&gt;=i+1;j--)&#123;//注意结束条件为j&gt;=i+1，不是j&gt;=0 if(nums[j]&gt;nums[i])&#123; swap(nums[i],nums[j]); reverse(nums.begin()+i+1,nums.end()); break;//注意反转之后需要跳出循环 &#125; &#125; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 复习一下
Codeclass Solution &#123;public: vector&lt;int&gt; twoSum(vector&lt;int&gt;&amp; nums, int target) &#123; unordered_map&lt;int,int&gt;h; vector&lt;int&gt;ans; int n=nums.size(); for(int i=0;i&lt;n;i++) &#123; if(h.count(target-nums[i])) &#123; ans.push_back(h[target-nums[i]]); ans.push_back(i); return ans; &#125; else h[nums[i]]=i; &#125; return ans; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(n)

题目 综述 使用两个指针 node1，node2 分别指向两个链表 headA，headB 的头结点， 同时分别逐结点遍历，当 node1 到达链表 headA 的末尾时，重新定位到链表 headB 的头结点； 当 node2 到达链表 headB 的末尾时，重新定位到链表 headA 的头结点。 当它们相遇时，所指向的结点就是第一个公共结点。
Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode(int x) : val(x), next(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) &#123; ListNode *pa=headA; ListNode *pb=headB; while(pa!=pb)&#123; // if(pa==pb&amp;&amp;pb==NULL)return NULL; pa!=NULL ? pa=pa-&gt;next :pa=headB; pb!=NULL ? pb=pb-&gt;next :pb=headA; &#125; return pa; &#125;&#125;;
复杂度分析 时间复杂度：O(N) 空间复杂度：O(1)

题目 综述 https://leetcode-cn.com/problems/maximum-product-subarray/solution/xiang-xi-tong-su-de-si-lu-fen-xi-duo-jie-fa-by--36/
Codeclass Solution &#123;public: int max_(int a,int b,int c)&#123; return max(max(a,b),c); &#125; int min_(int a,int b,int c)&#123; return min(min(a,b),c); &#125; int maxProduct(vector&lt;int&gt;&amp; nums) &#123; int len=nums.size(); int dpmax=nums[0]; int dpmin=nums[0]; int ans=nums[0]; for(int i=1;i&lt;len;i++)&#123; int temp=dpmax;//更新dpmin时需要dpmax的前一个值 dpmax=max_(dpmax*nums[i],dpmin*nums[i],nums[i]); dpmin=min_(temp*nums[i],dpmin*nums[i],nums[i]); ans=max(ans,dpmax); &#125; return ans; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 股票问题系列全解 求解对于某天i来说的最低历史价格，那么状态可以表示为 dp[i]，状态转移方程为dp[i] = min(dp[i-1],prices[i-1])； 对于每天而言的最大利润可以表示为price[i] - dp[i]，所有日期里利润最大那一天的利润就是最大的利润； 再考虑到对后面的天数而言，前面的天数只有历史最低价有意义，那么可以直接回收dp的空间，所以可以直接写出这样的代码
Codeclass Solution &#123;public: int maxProfit(vector&lt;int&gt;&amp; prices) &#123; int cur_min=prices[0],res=0; for(int i=1;i&lt;prices.size();i++) &#123; res=max(res,prices[i]-cur_min); cur_min=min(cur_min,prices[i]); &#125; return res; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 先做二叉树的直径 唯一的区别是：不是求边长，而是路径上节点的value之和，因为节点的value可能是负数，因此求左孩子右孩子的时候要int leftSum = max(0, dfs(root.left));舍弃掉负数的结果。
Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: int res=INT_MIN; int maxPathSum(TreeNode* root) &#123; depth(root); return res; &#125; int depth(TreeNode* root)&#123; //函数的作用是求得包含root节点的单边分支最大和 if(!root)return 0; //计算左边分支最大值，左边分支如果为负数还不如不选择 int left_depth=max(depth(root-&gt;left),0); //计算右边分支最大值，右边分支如果为负数还不如不选择 int right_depth=max(depth(root-&gt;right),0); //全局找最大值 res=max(res,left_depth+right_depth+root-&gt;val); //返回值需注意加上当前节点值 return max(left_depth,right_depth)+root-&gt;val; &#125;&#125;;
复杂度分析

题目
综述Code
中序迭代遍历

/** * Definition for a binary tree node. * struct TreeNode &#123; *     int val; *     TreeNode *left; *     TreeNode *right; *     TreeNode() : val(0), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) &#123;&#125; * &#125;; */class Solution &#123;public:    vector&lt;int&gt; inorderTraversal(TreeNode* root) &#123;        vector&lt;int&gt;res;        stack&lt;TreeNode*&gt;st;        while(root||!st.empty())        &#123;            if(root)            &#123;                st.push(root);                root=root-&gt;left;            &#125;            else            &#123;                auto t=st.top();                res.push_back(t-&gt;val);                st.pop();                root=t-&gt;right;            &#125;        &#125;        return res;    &#125;&#125;;


前序迭代遍历

/** * Definition for a binary tree node. * struct TreeNode &#123; *     int val; *     TreeNode *left; *     TreeNode *right; *     TreeNode() : val(0), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) &#123;&#125; * &#125;; */class Solution &#123;public:    vector&lt;int&gt; preorderTraversal(TreeNode* root) &#123;        vector&lt;int&gt;res;        stack&lt;TreeNode*&gt;st;        while(root||!st.empty())        &#123;            if(root)            &#123;                res.push_back(root-&gt;val);                st.push(root);                root=root-&gt;left;            &#125;            else            &#123;                auto t=st.top();                st.pop();                root=t-&gt;right;            &#125;        &#125;        return res;    &#125;&#125;;


后序迭代遍历
先遍历左子树，再遍历右子树


/** * Definition for a binary tree node. * struct TreeNode &#123; *     int val; *     TreeNode *left; *     TreeNode *right; *     TreeNode() : val(0), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) &#123;&#125; *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) &#123;&#125; * &#125;; */class Solution &#123;public:    vector&lt;int&gt; postorderTraversal(TreeNode* root) &#123;        stack&lt;TreeNode*&gt;st;        vector&lt;int&gt;res;        TreeNode *prev=nullptr;//最后从右子树依次向上返回时用于标记右子树已经被访问过        while(!st.empty()||root)        &#123;            while(root)            &#123;                st.push(root);                root=root-&gt;left;            &#125;            root=st.top();            if(!root-&gt;right||root-&gt;right==prev)//条件成立说明右子树已经遍历过            &#123;                res.push_back(root-&gt;val);                st.pop();                prev=root;//标记当前节点被访问过                root=nullptr;//根节点已经被访问，说明整个子树已经遍历完成，设置为空，下次循环弹出下一个栈顶元素            &#125;            else                root=root-&gt;right;        &#125;        return res;    &#125;&#125;;

前序遍历：根左右
变形：根右左
后续遍历：反转上面的
class Solution &#123;public:    vector&lt;int&gt;ans;    vector&lt;int&gt; postorderTraversal(TreeNode* root) &#123;        if(!root)return ans;        stack&lt;TreeNode*&gt;st;        while(root||st.size())        &#123;            if(root)            &#123;                ans.push_back(root-&gt;val);                st.push(root);                root=root-&gt;right;            &#125;            else            &#123;                auto t=st.top();                st.pop();                root=t-&gt;left;            &#125;        &#125;        reverse(ans.begin(),ans.end());        return ans;    &#125;&#125;;

复杂度分析
时间复杂度：O(n)
空间复杂度：O(n)

题目
综述Code/** * Definition for a binary tree node. * struct TreeNode &#123; *     int val; *     TreeNode *left; *     TreeNode *right; *     TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public:    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) &#123;        if(!root||root==p||root==q)return root;        auto l=lowestCommonAncestor(root-&gt;left,p,q);        auto r=lowestCommonAncestor(root-&gt;right,p,q);        if(l&amp;&amp;r)return root;        if(l)return l;        return r;    &#125;&#125;;

