题目 综述 先排出现次数最多的，以n+1为周期，细节见代码注释
Codeclass Solution &#123;public: int leastInterval(vector&lt;char&gt;&amp; tasks, int n) &#123; int len=tasks.size(); int map[26]=&#123;0&#125;; for(int i=0;i&lt;len;i++)&#123; map[tasks[i]-&#x27;A&#x27;]++; &#125; int time=0; sort(map,map+26); while(map[25]&gt;0)&#123;//结束的条件是所有任务全部排好 for(int i=0;i&lt;n+1;i++)&#123;//n+1为周期进行任务排列,先排任务数最多的种类 //这句代码非常重要，不能缺少。（map[25]==0说明此种任务已经排完，后续不会出现此种任务导致排列不合法，因此，跳出本层循环，开启新一轮n+1）如果缺少这段代码，可能导致最终结果偏大，因为后面可能map值都是0，但还是要走完n+1 if(map[25]==0)break; if(i&lt;26&amp;&amp;map[25-i]&gt;0)&#123; map[25-i]--; &#125; time++; &#125; sort(map,map+26); &#125; return time; &#125;&#125;;
复杂度分析时间复杂度：O(time) 空间复杂度：O(1)

题目 综述 dummy节点的设置：next指针指向头结点
Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode(int x) : val(x), next(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* deleteNode(ListNode* head, int val) &#123; ListNode* dummy=new ListNode(0); dummy-&gt;next=head;//设置虚拟节点，指向头指针 ListNode* cur=head; ListNode* pre=dummy; while(cur)&#123; if(cur-&gt;val==val)&#123; pre-&gt;next=cur-&gt;next; break; &#125; pre=cur; cur=cur-&gt;next; &#125; return dummy-&gt;next;//注意 &#125;&#125;;
复杂度分析 时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 TopK问题： 堆（可在一台计算机上进行流处理）； 随机选择算法(快排变形，可利用分布式的思想，在不同计算机并行处理，最后合并)； BFPRT算法？
快速排序： 单路快排 双路快排 三路快排（荷兰国旗问题）参考链接
注意本题中的c++代码写法
Code快速选择class Solution &#123;public: vector&lt;int&gt; topKFrequent(vector&lt;int&gt;&amp; nums, int k) &#123; vector&lt;int&gt;ans; unordered_map&lt;int,int&gt;h; for(auto num : nums)h[num]++; vector&lt;pair&lt;int,int&gt;&gt;arr; for(auto kv:h)arr.push_back(kv); int index=quick_sort(arr,0,arr.size()-1,k); for(int i=0;i&lt;=index;i++)ans.push_back(arr[i].first); return ans; &#125; int quick_sort(vector&lt;pair&lt;int,int&gt;&gt;&amp; arr, int l,int r, int k) &#123; if(l==r)return l; int i=l-1,j=r+1; auto x=arr[l + r &gt;&gt; 1]; while(i&lt;j) &#123; do i++;while(arr[i].second&gt;x.second); do j--;while(arr[j].second&lt;x.second); if(i&lt;j)swap(arr[i],arr[j]); &#125; if(k&lt;=j-l+1)return quick_sort(arr,l,j,k); else return quick_sort(arr,j+1,r,k-j+l-1); &#125;&#125;;
堆class Solution &#123;public: class cmp&#123;//小顶堆写法牢记 public: bool operator()(const pair&lt;int,int&gt;&amp; a,const pair&lt;int,int&gt;&amp; b)&#123; return a.second&gt;b.second; &#125; &#125;; vector&lt;int&gt; topKFrequent(vector&lt;int&gt;&amp; nums, int k) &#123; vector&lt;int&gt;res; unordered_map&lt;int,int&gt;mp; priority_queue&lt;pair&lt;int,int&gt;,vector&lt;pair&lt;int,int&gt; &gt;,cmp&gt;pq; for(int num:nums)&#123; mp[num]++; &#125; auto it=mp.begin(); while(it!=mp.end())&#123; pq.push(*it); if(pq.size()&gt;k)&#123;//保持pq的大小为k pq.pop(); &#125; it++; &#125; while(k--)&#123; res.push_back(pq.top().first); pq.pop(); &#125; return res; &#125;&#125;;
复杂度分析时间复杂度：O(nlogk) 空间复杂度：O(n)

题目 综述 迭代：由于需要链表前驱节点的信息，因此需要一个变量保存当前节点的前一个节点：pre是cur节点的前一个节点,两个节点依次后移 递归写法
Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode(int x) : val(x), next(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* reverseList(ListNode* head) &#123; if(!head||!head-&gt;next)return head; ListNode *pre=head; ListNode *cur=head-&gt;next; while(cur) &#123; ListNode *t=cur-&gt;next; cur-&gt;next=pre; pre=cur; cur=t; &#125; head-&gt;next=nullptr; return pre; &#125;&#125;; class Solution &#123;public: ListNode* reverseList(ListNode* head) &#123; if(!head||!head-&gt;next)return head; auto ans=reverseList(head-&gt;next); head-&gt;next-&gt;next=head; head-&gt;next=nullptr; return ans; &#125;&#125;;
复杂度分析

题目 综述归并排序思路 Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) &#123;&#125; * ListNode(int x) : val(x), next(nullptr) &#123;&#125; * ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* mergeKLists(vector&lt;ListNode*&gt;&amp; lists) &#123; return merge_sort(lists,0,lists.size()-1); &#125; ListNode* merge_sort(vector&lt;ListNode*&gt;&amp; lists,int l,int r) &#123; if(l&gt;r)return nullptr; if(l==r)return lists[l]; int mid=(l+r)&gt;&gt;1; auto left=merge_sort(lists,l,mid); auto right=merge_sort(lists,mid+1,r); return merge(left,right); &#125; ListNode* merge(ListNode *a,ListNode *b) &#123; if(!a)return b; if(!b)return a; if(a-&gt;val&lt;=b-&gt;val) &#123; a-&gt;next=merge(a-&gt;next,b); return a; &#125; else &#123; b-&gt;next=merge(a,b-&gt;next); return b; &#125; &#125;&#125;;
复杂度分析 时间复杂度：O(nlogn)
空间复杂度：O(1)

题目 综述 dp[i]表示字符串s，以下标i开始到最后的字符串是否可被 wordDict 拆分（这里下标i从s.size()-1开始求解，倒着递推） 注意substr的用法
Codeclass Solution &#123;public: bool wordBreak(string s, vector&lt;string&gt;&amp; wordDict) &#123; unordered_set&lt;string&gt;m(wordDict.begin(),wordDict.end()); int len=s.size(); vector&lt;int&gt;dp(len+5,0); //dp[i]表示字符串s，以下标i开始到最后的字符串是否可被 wordDict 拆分 dp[s.size()]=1;//初始化 for(int i=s.size()-1;i&gt;=0;i--)&#123;//倒着求dp[i]的值 for(int j=s.size();j&gt;i;j--)&#123; //关于j的取值范围，需要仔细推敲；可以结合特殊样例分析，比如想想如何求解dp[s.size()-1] if(dp[j]&amp;&amp;m.count(s.substr(i,j-i)))&#123;//字符串s[i,j-1]在字典中，且 dp[j]为真，所以此时dp[i]为真 dp[i]=true; break;//重要，找到之后就可以跳出了 &#125; &#125; &#125; return dp[0];//dp[0]的结果代表整个字符串是否满足结果 &#125;&#125;;
复杂度分析时间复杂度：O(n^2) 空间复杂度：O(n)

题目 综述 https://leetcode-cn.com/problems/he-wei-sde-lian-xu-zheng-shu-xu-lie-lcof/solution/shi-yao-shi-hua-dong-chuang-kou-yi-ji-ru-he-yong-h/
Codeclass Solution &#123;public: vector&lt;vector&lt;int&gt;&gt; findContinuousSequence(int target) &#123; int low=1; int high=1; int sum=0; vector&lt;vector&lt;int&gt; &gt;res; while(low&lt;=target/2)&#123;//左边界不可能比target/2大 if(sum&lt;target)&#123; sum+=high; high++; &#125; else if(sum&gt;target)&#123; sum-=low; low++; &#125; else&#123; vector&lt;int&gt;t; for(int i=low;i&lt;high;i++)t.push_back(i); res.push_back(t); sum-=low; low++; &#125; &#125; return res; &#125;&#125;;
