题目
综述
首先进行排序

注意如何剪枝

if(i&gt;0&amp;&amp;s[i]&#x3D;&#x3D;s[i-1]&amp;&amp;!flag[i-1])continue;
//i&gt;0保证i-1不越界，s[i]==s[i-1]保证第一个可以被递归//flag[i-1]==0,代表i-1已经先被递归而且结束，然后回溯到开始的地方，此时后面如果再相等，则剪枝

可画图理解



Codeclass Solution &#123;public:    int flag[10]=&#123;0&#125;;    vector&lt;string&gt;res;    string t=&quot;&quot;;    vector&lt;string&gt; permutation(string s) &#123;        sort(s.begin(),s.end());//先排序（字符串string排序方法）        dfs(0,s,s.size());        return res;    &#125;    void dfs (int nowk,string s,int n)&#123;        if(nowk==n)&#123;            res.push_back(t);            return;        &#125;        for(int i=0;i&lt;n;i++)&#123;            if(flag[i]==1)continue;            if(i&gt;0&amp;&amp;s[i]==s[i-1]&amp;&amp;!flag[i-1])continue;            //i&gt;0保证i-1不越界，s[i]==s[i-1]保证第一个可以被递归            //flag[i-1]==0,代表i-1已经先被递归，然后被回溯到这里，此时后面如果再相等，则跳过            flag[i]=1;            t+=s[i];            dfs(nowk+1,s,n);            t.pop_back();//字符串从尾部删除            flag[i]=0;        &#125;    &#125;&#125;;

