题目 综述 注释
Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Codec &#123;public: // Encodes a tree to a single string. string serialize(TreeNode* root) &#123; ostringstream out; queue&lt;TreeNode*&gt;q; q.push(root); while(q.size()) &#123; auto t=q.front(); q.pop(); if(t) &#123; out&lt;&lt;to_string(t-&gt;val)+&quot; &quot;; q.push(t-&gt;left); q.push(t-&gt;right); &#125; else out&lt;&lt;&quot;null &quot;; &#125; cout&lt;&lt;out.str(); return out.str();//注意用法 //对于所给样例，最终返回的字符串如下（最后存在一个空格）： //&quot;1 2 3 null null 4 5 null null null null &quot; &#125; // Decodes your encoded data to tree. TreeNode* deserialize(string data) &#123; vector&lt;TreeNode*&gt;q; istringstream input(data);//注意用法 string str; while(input&gt;&gt;str) &#123; if(str==&quot;null&quot;)q.push_back(nullptr); else q.push_back(new TreeNode(stoi(str))); &#125; int i=0,j=1;//i为当前节点下标,j为当前节点左子树根节点的下标 for(;j&lt;q.size();i++)//判断条件是j，因为j先到达结尾 &#123; //为空时直接跳过，不需要j++的原因是序列化时，为空的时候没有对其左右子树序列化，导致少了2位 //因此后面的节点的下标将前移2位，这样到最后正好遍历完。 if(!q[i])continue; q[i]-&gt;left=q[j++]; q[i]-&gt;right=q[j++]; &#125; return q[0]; &#125;&#125;;// Your Codec object will be instantiated and called as such:// Codec ser, deser;// TreeNode* ans = deser.deserialize(ser.serialize(root));
复杂度分析

题目 综述 见注释
Codeclass Solution &#123;public: int rob(vector&lt;int&gt;&amp; nums) &#123; int len=nums.size(); if(len==0)return 0; if(len==1)return nums[0]; if(len==2)return max(nums[0],nums[1]); //有三种可能：选择第一个，不选择最后一个；选择最后一个，不选择第一个；两个都不选（由于全为正数，此种情况明显要小） return max(help(0,len-2,nums),help(1,len-1,nums)); &#125; //以下为打家劫舍1的解法 int help(int start,int end,vector&lt;int&gt;&amp; nums)&#123; int a=nums[start]; int b=max(nums[start+1],nums[start]); for(int i=start+2;i&lt;=end;i++)&#123; int t=b; b=max(b,nums[i]+a); a=t; &#125; return b; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 递推关系为偷前k-1个或者前k-2个+当前的最大值
Codeclass Solution &#123;public: int rob(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); if(!n)return 0; vector&lt;int&gt;f(n+1,0); f[1]=nums[0]; for(int i=2;i&lt;=n;i++) &#123; f[i]=max(nums[i-1]+f[i-2],f[i-1]); &#125; return f[n]; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 树的问题，很多时候需要先知道叶子结点的信息，然后才能决定当前结点的信息是什么，所以这种遍历顺序就是后序遍历，这道题还有第 236 题：二叉树的最近公共祖先 都是后序遍历。二叉树里的问题，不外乎就是前序、中序、后序遍历、还有广度优先遍历，后序遍历其实出现的概率更多一点。这种遍历的思想比较重要，在解决一些问题的时候很有用。 https://leetcode-cn.com/problems/house-robber-iii/solution/shu-xing-dp-ru-men-wen-ti-by-liweiwei1419/
Codeclass Solution &#123; //记忆化递归方法public: unordered_map&lt;TreeNode*,int&gt;mp; int rob(TreeNode* root) &#123; if(root==NULL)return 0; if(mp.count(root))return mp[root]; //偷四个孙子 int do_=root-&gt;val+(root-&gt;left?rob(root-&gt;left-&gt;left)+rob(root-&gt;left-&gt;right):0)+(root-&gt;right?rob(root-&gt;right-&gt;left)+rob(root-&gt;right-&gt;right):0); //偷两个孩子 int undo=rob(root-&gt;left)+rob(root-&gt;right); int res=max(do_,undo); mp[root]=res; return res; &#125;&#125;; class Solution &#123;// 树的后序遍历public: int rob(TreeNode* root) &#123; vector&lt;int&gt;ans=dfs(root); return max(ans[0],ans[1]); &#125; vector&lt;int&gt; dfs(TreeNode*node)&#123; vector&lt;int&gt;dp(2,0); if(node==NULL)return dp; // 分类讨论的标准是：当前结点偷或者不偷 // 由于需要后序遍历，所以先计算左右子结点，然后计算当前结点的状态值 vector&lt;int&gt;left=dfs(node-&gt;left); vector&lt;int&gt;right=dfs(node-&gt;right); //dp[0]代表不偷当前节点时的最大值 dp[0]=max(left[0],left[1])+max(right[0],right[1]); //dp[1]代表偷当前节点时的最大值 dp[1]=node-&gt;val+left[0]+right[0]; return dp; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 以现在我的理解，再来说说这道题目。这道题目属于一道经典的 区间DP 的题目，在计算这种问题时，通常第一维度是从小到大来枚举区间的长度（规模）；第二维度枚举一个 k 来计算当前长度（规模）的值。如果从这个角度来理解的话，我们应该不难想到状态空间的表示可以用一个二维的数组来表示了。dp[i][j]，i 代表区间的上限，j 代表区间的下限。 回溯+记忆化递归+区间dp
Codeclass Solution &#123;public: /*记忆化递归 vector&lt;vector&lt;int&gt; &gt;dp; int help(vector&lt;int&gt;&amp; nums, int i,int j)&#123; if(i&gt;j)return 0; if(dp[i][j]&gt;0)return dp[i][j]; for(int k=i;k&lt;=j;k++)&#123; int left=help(nums,i,k-1); int right=help(nums,k+1,j); int t=nums[k]*nums[i-1]*nums[j+1]; dp[i][j]=max(dp[i][j],left+t+right); &#125; return dp[i][j]; &#125; int maxCoins(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); dp = vector&lt;vector&lt;int&gt; &gt;(n + 2, vector&lt;int&gt;(n + 2, 0)); nums.insert(nums.begin(), 1); nums.push_back(1); return help(nums,1,n); &#125; */ int maxCoins(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); vector&lt;vector&lt;int&gt; &gt;dp(n + 2, vector&lt;int&gt;(n + 2, 0)); nums.insert(nums.begin(), 1); nums.push_back(1); for(int len=1;len&lt;=n;len++)&#123; for(int i=1;i&lt;=n-len+1;i++)&#123; int j=i+len-1; for(int k=i;k&lt;=j;k++)&#123; dp[i][j]=max(dp[i][j],dp[i][k-1]+nums[k]*nums[i-1]*nums[j+1]+dp[k+1][j]); &#125; &#125; &#125; return dp[1][n]; &#125;&#125;;
复杂度分析时间复杂度：O(n^3) 空间复杂度：O(n^2)

题目 综述 Codeclass Solution &#123;public: int trap(vector&lt;int&gt;&amp; height) &#123; int leftmax=0,rightmax=0; int i=0,j=height.size()-1; int res=0; while(i&lt;j) &#123; leftmax=max(leftmax,height[i]); rightmax=max(rightmax,height[j]); if(leftmax&lt;rightmax) res+=leftmax-height[i++]; else res+=rightmax-height[j--]; &#125; return res; &#125;&#125;;
单调栈解法 对于每个元素，找其左右两边第一个大于当前元素的下标 当前元素（栈顶元素t），左边第一个大于当前元素的下标（栈顶下面的元素），右边第一个大于当前元素的下标（height[i]），三者形成雨水 class Solution &#123;public: int trap(vector&lt;int&gt;&amp; height) &#123; int n=height.size(); stack&lt;int&gt;stk; int res=0; for(int i=0;i&lt;n;i++) &#123; while(!stk.empty()&amp;&amp;height[i]&gt;height[stk.top()]) &#123; int t=stk.top(); stk.pop(); while(!stk.empty()&amp;&amp;height[stk.top()]==height[t]) stk.pop(); if(!stk.empty()) res+=(i-stk.top()-1)*(min(height[stk.top()],height[i])-height[t]);//长*高 &#125; stk.push(i); &#125; return res; &#125;&#125;;
复杂度分析 时间复杂度：O(n)
空间复杂度：O(1)

题目 综述 先找到反转点，然后分别二分搜索
Codeclass Solution &#123;public: int help(vector&lt;int&gt;&amp; nums,int l,int r,int &amp;target) &#123; while(l&lt;=r) &#123; int mid=(l+r)/2; if(target==nums[mid])return mid; else if(target&gt;nums[mid])l=mid+1; else r=mid-1; &#125; return -1; &#125; int search(vector&lt;int&gt;&amp; nums, int target) &#123; int l=0,r=nums.size()-1; while(l&lt;r) &#123; int mid=(l+r)/2; if(nums[mid]&lt;nums[0])r=mid; else l=mid+1; &#125; int t=l; return max(help(nums,0,t-1,target),help(nums,t,nums.size()-1,target)); &#125;&#125;;
复杂度分析时间复杂度：O(logn) 空间复杂度：O(1)

题目 综述 随机选择算法：算法笔记149页；写之前需参考：快排全解这篇笔记。、 小顶堆写法 把数据依次送入小顶堆，当堆内元素个数为K+1时就弹出堆顶元素。 最终得到的元素个数为K的小顶堆的堆顶元素就是答案。
Code随机选择算法双路partition写法class Solution &#123;public: int findKthLargest(vector&lt;int&gt;&amp; arr, int k) &#123; int nk=arr.size()-k+1;//第k个最大的元素相当于排序数组的第nk个元素 return randselect(arr,nk,0,arr.size()-1); &#125; int randselect(vector&lt;int&gt;&amp; arr,int nk,int left,int right)&#123; swap(arr[left],arr[rand()%(right-left+1)+left]); int temp=arr[left]; int low=left; int high=right; while(low&lt;high)&#123; while(low&lt;high&amp;&amp;arr[high]&gt;=temp)high--; arr[low]=arr[high]; while(low&lt;high&amp;&amp;arr[low]&lt;=temp)low++; arr[high]=arr[low]; &#125; swap(temp,arr[low]); //以上代码与快排写法完全一致 //下面代码是快速选择算法特有 //arr[low]是整个区间的第low-left+1个数:用M表示 int M=low-left+1; if(nk&lt;M)&#123;//答案在区间[left,low-1]中 return randselect(arr,nk,left,low-1); &#125;else if(nk&gt;M)&#123;//答案在区间[low+1,right]中 return randselect(arr,nk-M,low+1,right); &#125;else &#123;//找到答案，即arr[low] return arr[low]; &#125; &#125;&#125;;
三路partition写法class Solution &#123;public: int findKthLargest(vector&lt;int&gt;&amp; arr, int k) &#123; int nk=arr.size()-k+1;//第k个最大的元素相当于排序数组的第nk个元素 return randselect(arr,nk,0,arr.size()-1); &#125; int randselect(vector&lt;int&gt;&amp; arr,int nk,int left,int right)&#123; swap(arr[left],arr[rand()%(right-left+1)+left]); int temp=arr[left]; int i=left; int lt=left-1; int gt=right+1; while(i&lt;gt)&#123; if(temp==arr[i])&#123; ++i; &#125;else if(temp&gt;arr[i])&#123; swap(arr[i++],arr[++lt]); &#125;else&#123; swap(arr[i],arr[--gt]); &#125; &#125; //以上代码与快排写法完全一致 //下面代码是快速选择算法特有 /* 经过一次partition:划分得到的区间如下 区间：arr[low...lt] &lt; temp 区间：arr[gt...high] &gt; temp 区间：arr[lt+1...i) == temp 也即 arr[lt+1...gt-1] == temp */ //arr[lt+1]是整个区间的第lt-left+2个数:用al表示 //arr[gt-1]是整个区间的第gt-left个数:用ar表示 int al=lt-left+2; int ar=gt-left; if(nk&lt;al)&#123;//答案在区间[left,lt]中 return randselect(arr,nk,left,lt); &#125;else if(nk&gt;ar)&#123;//答案在区间[gt,right]中 return randselect(arr,nk-ar,gt,right); &#125;else &#123;//找到答案，即arr[lt+1...gt-1] 区间的任意一个数 return arr[lt+1]; &#125; &#125;&#125;;
小顶堆写法class Solution &#123;public: struct cmp&#123;//小顶堆写法牢记 bool operator() (int a,int b)&#123;//不要漏写括号 return a&gt;b; &#125; &#125;; int findKthLargest(vector&lt;int&gt;&amp; arr, int k) &#123; priority_queue&lt;int,vector&lt;int&gt;,cmp&gt;pq;//不要漏写cmp for(int num:arr)&#123; pq.push(num); if(pq.size()==k+1)&#123; pq.pop(); &#125; &#125; return pq.top(); &#125;&#125;;
复杂度分析 时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 先转置，然后逐行反转
Codeclass Solution &#123;public: void rotate(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; int n=matrix.size(); for(int i=0;i&lt;n;i++)&#123;//下对角线翻到上对角线 for(int j=0;j&lt;i;j++)&#123; swap(matrix[i][j],matrix[j][i]); &#125; &#125; for(int i=0;i&lt;n;i++)&#123;//逐行反转 for(int j=0;j&lt;n/2;j++)&#123; swap(matrix[i][j],matrix[i][n-j-1]); &#125; &#125; &#125;&#125;; class Solution &#123;public: void rotate(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; int n=matrix.size(); for(int i=0;i&lt;n/2;i++)//共有n/2圈 for(int j=i;j&lt;n-i-1;j++)//每一圈考虑第一个到倒数第二个元素，第一圈是[0,n-1)...=&gt;[i,n-i-1) &#123; //反转关系是[i,j]=&gt;[j,n-i-1] int cur=matrix[i][j],r=j,c=n-i-1; for(int i=0;i&lt;4;i++)//进行四次反转,每次循环找出下一次的r和c &#123; swap(cur,matrix[r][c]); int tmp=r; r=c; c=n-tmp-1; &#125; &#125; &#125;&#125;;
复杂度分析时间复杂度：O(n^2) 空间复杂度：O(1)

题目 综述
把最右侧相等的元素去掉，此时区间就满足左边的都大于等于nums[0]，右边的都小于nums[0]，找到右边第一个小于nums[0]的元素即可 注释中的细节需要注意 Codeclass Solution &#123;public: int findMin(vector&lt;int&gt;&amp; nums) &#123; int j=nums.size()-1; while(j&gt;0&amp;&amp;nums[0]==nums[j])j--;//这里是j&gt;0,不包含等于 if(nums[j]&gt;=nums[0])return nums[0]; int l=0,r=j; while(l&lt;r) &#123; int mid=(l+r)/2; if(nums[mid]&lt;nums[0])r=mid; else l=mid+1; &#125; return nums[r]; &#125;&#125;;
复杂度分析时间复杂度：O(logn)，重复元素导致最差时间复杂度是O(n) 空间复杂度：O(1)

题目 综述 转化为最大的矩形问题 见柱状图中最大的矩形问题解析
Codeclass Solution &#123;public: int largestRectangleArea(vector&lt;int&gt; heights) &#123;//这里传参本题不能使用引用，否则出错 int n=heights.size(); stack&lt;int&gt;stk; //左右边界值 heights.insert(heights.begin(),-1); heights.push_back(-1); int res=0; for(int i=0;i&lt;heights.size();i++) &#123; while(!stk.empty()&amp;&amp;heights[i]&lt;heights[stk.top()]) &#123; int t=stk.top(); stk.pop(); while(!stk.empty()&amp;&amp;heights[stk.top()]==heights[t]) stk.pop(); if(!stk.empty()) res=max(res,(i-stk.top()-1)*heights[t]); &#125; stk.push(i); &#125; return res; &#125; int maximalRectangle(vector&lt;vector&lt;char&gt;&gt;&amp; matrix) &#123; int m=matrix.size(); if(!m)return 0; int n=matrix[0].size(); int res=0; vector&lt;int&gt;heights(n,0); for(int i=0;i&lt;m;i++)//逐行更新heights数组 &#123; for(int j=0;j&lt;n;j++) &#123; //以下if..else..块中代码写法要牢记 if(matrix[i][j]==&#x27;1&#x27;)//这个判断条件不同问题还可换成不同的判断逻辑 heights[j]++; else heights[j]=0; &#125; res=max(res,largestRectangleArea(heights)); &#125; return res; &#125;&#125;;
复杂度分析时间复杂度：O(m*n) 空间复杂度：O(n)

题目 综述 子序列是不一定连续的，子串是连续的 最长上升子序列模型需要牢记
Codetail[i]表示长度为i的最长上升子序列，这个子序列最后一个数的值。因此，这个值越小越好，tail数组下标的范围是[1，n]。这个数组的长度就是本题的答案 如何构造这个数组： 对于原数组中每一个数nums[i]，我要把它放在tail数组合适的位置。假设j是tail数组中最后一个小于nums[i]的位置，我们应该把nums[i]放在tails[j+1]的位置，同时不断更新tail数组的长度 class Solution &#123;public: int lengthOfLIS(vector&lt;int&gt;&amp; nums) &#123; int res=0; int n=nums.size(); if(n==0)return res; vector&lt;int&gt;tail(n+1,0); for(int i=0;i&lt;nums.size();i++)&#123; int l=0,r=res; while(l&lt;r)&#123;//在tail数组中二分找到最后一个小于nums[i]的位置 int mid=(l+r+1)&gt;&gt;1; if(tail[mid]&lt;nums[i])l=mid; else r=mid-1; &#125; tail[l+1]=nums[i]; res=max(res,l+1);//维护tail数组的最大长度 &#125; return res; &#125;&#125;;
以第i个数结尾的上升子序列 class Solution &#123;public: int lengthOfLIS(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); int res=0; vector&lt;int&gt;f(n,0); for(int i=0;i&lt;n;i++) &#123; f[i]=1;//这里必须先取1 for(int j=0;j&lt;i;j++) if(nums[i]&gt;nums[j]) f[i]=max(f[i],f[j]+1); res=max(res,f[i]);//在这里找最大值 &#125; return res; &#125;&#125;;
复杂度分析时间复杂度：O(nlogn) 空间复杂度：O(n)

题目 综述Code中心扩散法 class Solution &#123;public: string help(string &amp;s, int l,int r)&#123; int n=s.size(); while(l&gt;=0&amp;&amp;r&lt;n&amp;&amp;s[l]==s[r])&#123;//注意边界条件的处理 l--; r++; &#125; return s.substr(l+1,r-l-1); &#125; string longestPalindrome(string s) &#123; int n=s.size(); string res; for(int i=0;i&lt;n;i++)&#123; string s1=help(s,i,i); string s2=help(s,i,i+1); res=res.size()&gt;s1.size()? res :s1; res=res.size()&gt;s2.size()? res :s2; &#125; return res; &#125;&#125;;
字符串哈希 class Solution &#123;public: typedef unsigned long long ULL; static const int N=2010;//开为2倍 ULL p[N],hl[N],hr[N]; int base=131; char str[N]; ULL get(ULL h[],int l,int r) &#123; return h[r]-h[l-1]*p[r-l+1]; &#125; string longestPalindrome(string s) &#123; int n=s.size(); for(int i=2*n;i&gt;0;i-=2) &#123; str[i]=s[i/2-1]; str[i-1]=&#x27;#&#x27;; &#125;//从1开始 // puts(str+1); n*=2; p[0]=1;//不能少 for(int i=1,j=n;i&lt;=n;i++,j--) &#123; p[i]=p[i-1]*base; hl[i]=hl[i-1]*base+str[i]-&#x27;a&#x27;+1; hr[i]=hr[i-1]*base+str[j]-&#x27;a&#x27;+1; &#125; int res=0,al,ar; for(int i=1;i&lt;=n;i++) &#123; int l=0,r=min(i-1,n-i); while(l&lt;r) &#123; int mid=(l+r+1)/2; if(get(hl,i-mid,i-1)!=get(hr,n-(i+mid)+1,n-(i+1)+1))r=mid-1; else l=mid; &#125; int cur_len=(str[i-l]==&#x27;#&#x27;?l:l+1); if(cur_len&gt;res) &#123; al=i-l,ar=i+l; res=cur_len; &#125; &#125; string ans; for(int i=al;i&lt;=ar;i++) if(str[i]!=&#x27;#&#x27;) ans+=str[i]; return ans; &#125;&#125;;
复杂度分析时间复杂度：O(n^2) 空间复杂度：O(1)

题目 综述 非常明确的是，第i位的值位前i位的累积✖️后i位的累积 先从左到右累积，第i位的值位前i-1位的累积 再从右到左累积，第i位的值为2.的结果乘上后i-1位的累积
Codeclass Solution &#123;public: vector&lt;int&gt; constructArr(vector&lt;int&gt;&amp; a) &#123; int n=a.size(); vector&lt;int&gt;ans(n); int t=1; for(int i=0;i&lt;n;i++)&#123; ans[i]=t; t*=a[i]; &#125; t=1; for(int i=n-1;i&gt;=0;i--)&#123; ans[i]*=t;//注意这里的区别 t*=a[i]; &#125; return ans; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目 综述官方题解视频讲解很清楚，重点看栈的模拟解释部分 哨兵技巧：头尾各插入一个-1的值，保证一定可以找到左右两边小于当前数的值 以当前柱子 i 的高度作为矩形的高，那么矩形的宽度边界即为向左找到第一个高度小于当前柱体 i 的柱体，向右找到第一个高度小于当前柱体 i 的柱体。中间的（不包括边界）就是矩形的宽度，高度就是当前柱子 i 的高度 对于每个元素，找其左右两边第一个小于当前元素的下标，和接雨水相反 当前元素（栈顶元素t），左边第一个小于当前元素的下标（栈顶下面的元素），右边第一个小于当前元素的下标（height[i]），三者形成雨水 Codeclass Solution &#123;public: int largestRectangleArea(vector&lt;int&gt;&amp; heights) &#123; int n=heights.size(); stack&lt;int&gt;stk; //左右边界值 heights.insert(heights.begin(),-1); heights.push_back(-1); int res=0; for(int i=0;i&lt;heights.size();i++) &#123; while(!stk.empty()&amp;&amp;heights[i]&lt;heights[stk.top()]) &#123; int t=stk.top(); stk.pop(); while(!stk.empty()&amp;&amp;heights[stk.top()]==heights[t]) stk.pop(); if(!stk.empty()) res=max(res,(i-stk.top()-1)*heights[t]); &#125; stk.push(i); &#125; return res; &#125;&#125;;
复杂度分析 时间复杂度：O(n)
空间复杂度：O(n)

题目
综述Code/** * Definition for a binary tree node. * struct TreeNode &#123; *     int val; *     TreeNode *left; *     TreeNode *right; *     TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public:    bool isSubStructure(TreeNode* A, TreeNode* B) &#123;        if (!A || !B) return false;        return dfs(A, B) || isSubStructure(A-&gt;left, B) || isSubStructure(A-&gt;right, B);        //注意这里的写法    &#125;        bool dfs(TreeNode* A, TreeNode* B) &#123;        if (!B) return true; //该判断只能写在最前面        if (!A) return false;        return A-&gt;val == B-&gt;val &amp;&amp; dfs(A-&gt;left, B-&gt;left) &amp;&amp; dfs(A-&gt;right, B-&gt;right);    &#125;&#125;;

复杂度分析

题目 综述单调栈模板题：求左边第一个大的就倒序，右边第一个小的就正序 Codeclass Solution &#123;public: vector&lt;int&gt; dailyTemperatures(vector&lt;int&gt;&amp; T) &#123; int n=T.size(); vector&lt;int&gt;ans(n); stack&lt;int&gt;stk; for(int i=n-1;i&gt;=0;i--) &#123; while(!stk.empty()&amp;&amp;T[i]&gt;=T[stk.top()]) stk.pop(); if(stk.size())ans[i]=stk.top()-i; else ans[i]=0; stk.push(i); &#125; return ans; &#125;&#125;;
复杂度分析 时间复杂度：O(n)
空间复杂度：O(n)

题目 综述 奇数一定比前一个偶数多1 偶数最后一位为0，一定与该偶数除以2相同，除以2相当于右移一位，即将最后的0抹去
Codeclass Solution &#123;public: vector&lt;int&gt; countBits(int num) &#123; vector&lt;int&gt;res(num+1,0); for(int i=1;i&lt;=num;i++)&#123; if(i&amp;1)&#123; res[i]=res[i-1]+1; &#125; else&#123; res[i]=res[i/2]; &#125; &#125; return res; &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(n)

题目 综述假设头结点到环的入口位置距离是a，环的大小是b。 快慢指针第一次相遇时，可以思考，他们一定是在环内相遇，因为有环的链表指针会一直在环内转圈。 假设相遇时，快指针走了f，慢指针走了s，则有f&#x3D;s+nb；&#x3D;&#x3D;&gt;因为快指针比慢指针多走了n个环的大小才相遇 同时有f&#x3D;2s；&#x3D;&#x3D;&gt;因为快指针每次走两步，慢指针每次走一步 以上可知，s&#x3D;nb，也就是说相遇时，慢指针走过的总长度是n个环的长度，慢指针再走a步就是环的入口【重要结论】
如果此时让一个指针从头结点开始走，那么它走到环的入口位置的长度是a+nb 也就是说如果此时让慢指针再走a步，就到了环的入口，但是不知道a的大小 此时，可以设置新的指针在头结点，和慢指针一块每次走一步，他们相遇时，就走了a步，且位置正好在环的入口 Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode(int x) : val(x), next(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode *detectCycle(ListNode *head) &#123; ListNode* fast=head; ListNode* slow=head; while(1) &#123; if(fast==NULL||fast-&gt;next==NULL)return NULL; slow=slow-&gt;next; fast=fast-&gt;next-&gt;next; if(slow==fast)break; &#125; fast=head;//从头开始走a步 while(fast!=slow)//再让慢指针走a步 &#123; slow=slow-&gt;next; fast=fast-&gt;next; &#125; return slow;//相遇时就是环的入口位置 &#125;&#125;;
复杂度分析时间复杂度：O(n) 空间复杂度：O(1)

题目
综述Codeclass Solution &#123;public:    vector&lt;string&gt;res;    string t;    unordered_map&lt;char, string&gt; mp&#123;        &#123;&#x27;2&#x27;, &quot;abc&quot;&#125;,&#123;&#x27;3&#x27;,&quot;def&quot;&#125;, &#123;&#x27;4&#x27;,&quot;ghi&quot;&#125;,         &#123;&#x27;5&#x27;,&quot;jkl&quot;&#125;,&#123;&#x27;6&#x27;,&quot;mno&quot;&#125;, &#123;&#x27;7&#x27;,&quot;pqrs&quot;&#125;,        &#123;&#x27;8&#x27;,&quot;tuv&quot;&#125;,&#123;&#x27;9&#x27;,&quot;wxyz&quot;&#125;&#125;;     vector&lt;string&gt; letterCombinations(string digits) &#123;        if(digits.size()==0)return res;        dfs(digits,0);        return res;    &#125;    void dfs(string &amp;digits,int u)    &#123;        if(u==digits.size())        &#123;            res.push_back(t);            return;        &#125;        string str=mp[digits[u]];//在每一个位置处，可能的字符只可能为digit[k]所代表的几个字母        for(char c:str)        &#123;            t+=c;            dfs(digits,u+1);            t.pop_back();        &#125;    &#125;&#125;;

