题目
综述
https://leetcode-cn.com/problems/target-sum/solution/c-dfshe-01bei-bao-by-bao-bao-ke-guai-liao/
如果是一个数组中挑几个数字和为目标和，这种题目可以直接用01背包动态规划求解。

Code//暴力超时class Solution &#123;public:    int findTargetSumWays(vector&lt;int&gt;&amp; nums, int S) &#123;        return dfs(nums,S,0);    &#125;    int dfs(vector&lt;int&gt;&amp; nums, long target,int k)&#123;        if(target==0&amp;&amp;k==nums.size())return 1;        if(k&gt;=nums.size())return 0;        int ans=0;        ans+=dfs(nums,target-nums[k],k+1);        ans+=dfs(nums,target+nums[k],k+1);        return ans;    &#125;&#125;;
//转化为0-1背包问题class Solution &#123;public:    int findTargetSumWays(vector&lt;int&gt;&amp; nums, int S) &#123;        //和有可能超出整数范围        long sum=0;        for(int num:nums)&#123;            sum+=num;        &#125;        //target的2倍不可能为奇数        if((sum+S)&amp;1)return 0;        //总和小于S直接返回        if(S&gt;sum)return 0;        int target=(sum+S)/2;        //注意dp数组的初始化        vector&lt;long&gt;dp(target+1,0);        dp[0]=1;        for(int num :nums)&#123;            for(int j=target;j&gt;=num;j--)&#123;                dp[j]+=dp[j-num];            &#125;        &#125;        return dp[target];    &#125;&#125;;

复杂度分析时间复杂度：O(n*target)
空间复杂度：O(target)

题目
综述f[n]表示有n个人时最终胜利者的编号
第一轮:f[n]淘汰的编号是m-1,之后重新编号,有以下关系①x-&gt;(x-m+n)%(n-1);
第二轮f[n-1]根据①&#x3D;&#x3D;&gt;(f[n]-m+n)%(n-1)&#x3D;f[n-1]=&#x3D;&gt;递推关系:f[n]=(f[n-1]+m)%(n-1)
初始情况:f[1]=0;
Codeclass Solution &#123;public:    int lastRemaining(int n, int m) &#123;        // queue&lt;int&gt;q;        // for(int i=0;i&lt;n;i++)q.push(i);        // while(q.size()&gt;1)&#123;        //     for(int i=0;i&lt;m-1;i++)&#123;        //         q.push(q.front());        //         q.pop();        //     &#125;        //     // return q.front();        //     q.pop();        // &#125;        // return q.front();        int p=0;//i=1时，最终胜利者的（位置）下标        for(int i=2;i&lt;=n;i++)&#123;//i代表此时队列里还有多少人            p=(p+m)%i;            //在剔除一个人后，胜利者的位置会前移m（下标-3），所以倒过来胜利者的位置后移（下标+3），防止超过队列长度取模        &#125;        return p;    &#125;&#125;;

复杂度分析时间复杂度：O(n)
空间复杂度：O(1)

