题目 综述 递归函数参数中的引用变量和全局变量都会随着递归全局变化，因此对于这些变量的改变要在递归语句之后进行回溯操作，恢复这些变量之前的值。 递归函数中的普通变量则不用。 本题的小细节：dfs方法保证每次进入的节点都是非空的，不然会出错
Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: vector&lt;vector&lt;int&gt; &gt;res; vector&lt;int&gt;t; vector&lt;vector&lt;int&gt;&gt; pathSum(TreeNode* root, int sum) &#123; if(!root)return res; dfs(root,sum); return res; &#125; void dfs(TreeNode* root,int sum)&#123; t.push_back(root-&gt;val); sum-=root-&gt;val; if(sum==0&amp;&amp;root-&gt;right==NULL&amp;&amp;root-&gt;left==NULL)&#123; res.push_back(t); return; &#125; if(root-&gt;left)&#123; dfs(root-&gt;left,sum); t.pop_back(); &#125; if(root-&gt;right)&#123; dfs(root-&gt;right,sum); t.pop_back(); &#125; &#125;&#125;;
复杂度分析

题目 综述方法1：双递归 方法2：前缀和 Code// 首先先序递归遍历每个节点，再以每个节点作为起始点递归寻找满足条件的路径。class Solution &#123;public: int count=0; int pathSum(TreeNode* root, int sum) &#123; if(root==NULL)return 0;//终止本轮递归 dfs(root,sum); pathSum(root-&gt;left,sum); pathSum(root-&gt;right,sum); return count; &#125; //对一个结点进行路径的判断 void dfs(TreeNode* root, int sum)&#123; if(root==NULL)return; sum-=root-&gt;val; if(sum==0)count++;//不应终止本轮递归 因为可能某条路径的子路径符合要求 dfs(root-&gt;left,sum); dfs(root-&gt;right,sum); &#125;&#125;; class Solution &#123;public: //mp中key为前缀和，value为前缀和的个数，mp初始化为0，同时key可以为负数 unordered_map&lt;int,int&gt;mp; int res=0; int pathSum(TreeNode* root, int sum) &#123; if(root==NULL)return 0; mp[0]=1; dfs(root,sum,0); return res; &#125; void dfs(TreeNode* root, int sum,int presum)&#123; //presum代表root路径之前的和 if(root==NULL)return; //root-&gt;val更新为包括当前节点的前缀和 root-&gt;val+=presum; //这里不用判断是否root-&gt;val-sum&gt;=0因为可能前缀和是负数 //接下来两行代码的顺序不能错，先利用mp的值再更新mp的值 res+=mp[root-&gt;val-sum]; mp[root-&gt;val]++; dfs(root-&gt;left,sum,root-&gt;val); dfs(root-&gt;right,sum,root-&gt;val); //回溯必须要有的 mp[root-&gt;val]--; &#125;&#125;;
复杂度分析 时间复杂度：O(n)
空间复杂度：O(n)

题目 综述设置两个指针，只有当前位置的字符被匹配后才去看下一个 Codeclass Solution &#123;public: bool isSubsequence(string s, string t) &#123; int k=0; for(int i=0;i&lt;t.size()&amp;&amp;k&lt;s.size();i++)&#123; if(s[k]==t[i])k++; &#125; return k==s.size(); &#125;&#125;;
思考题
dp[i][j]表示当前下标i之后的位置中第一次出现字符j+’a’的位置
对于 &quot;abc&quot; 在 &quot;ahbgdc&quot; 上匹配的时候，由于长字符串第一个 a 的下一个出现 a 的位置为 -1（不出现），会导致一个 bug。进行哨兵处理
class Solution &#123;public: bool isSubsequence(string s, string t) &#123; t.insert(t.begin(),&#x27; &#x27;);//2.哨兵处理 int n=t.size(); vector&lt;vector&lt;int&gt; &gt; dp(n,vector&lt;int&gt;(26,0)); for(char c=&#x27;a&#x27;;c&lt;=&#x27;z&#x27;;c++)&#123; int p=-1; for(int i=n-1;i&gt;=0;i--)&#123;//1.需要倒序 dp[i][c-&#x27;a&#x27;]=p; if(c==t[i])p=i; &#125; &#125; int index = 0; for (char c : s) &#123; index = dp[index][c - &#x27;a&#x27;]; if (index == -1) return false; &#125; return true; &#125;&#125;;
复杂度分析

如何手写一个堆?

插入一个数　　　　　heap[ ++ cnt] = x; up(cnt);
求集合当中的最小值　heap[1];
删除最小值　　　　　swap(heap[1],heap[cnt]); cnt -- ; down(1);
删除任意一个元素　　swap(heap[k],heap[cnt]); cnt -- ; down(k); up(k);
修改任意一个元素　　heap[k] = x; down(k); up(k);

// h[N]存储堆中的值, h[1]是堆顶，x的左儿子是2x, 右儿子是2x + 1// ph[k]=x表示第k个元素在堆中的x索引处// hp[x]=k表示堆中索引为x的地方存储的是第k个元素int h[N], ph[N], hp[N], cnt;// 交换两个点，及其映射关系void heap_swap(int a, int b)&#123;    swap(ph[hp[a]],ph[hp[b]]);    swap(hp[a], hp[b]);    swap(h[a], h[b]);&#125;void down(int u)&#123;    int t = u;    if (u * 2 &lt;= cnt &amp;&amp; h[u * 2] &lt; h[t]) t = u * 2;    if (u * 2 + 1 &lt;= cnt &amp;&amp; h[u * 2 + 1] &lt; h[t]) t = u * 2 + 1;    if (u != t)    &#123;        heap_swap(u, t);        down(t);    &#125;&#125;void up(int u)&#123;    while (u / 2 &amp;&amp; h[u] &lt; h[u / 2])    &#123;        heap_swap(u, u / 2);        u &gt;&gt;= 1;    &#125;&#125;// O(n)建堆//堆是完全二叉树，完全二叉树中有i/2个非叶子节点，且必须从下往上down//进行down(i)时需要保证i的左右两个儿子都已经满足堆的性质。从n / 2开始向前做，相当于从整棵二叉树的最后一层开始往上做，那么是可以保证这个性质的。但是如果从根节点向下做，则第一次就不满足这个性质了//n / 2是从倒数第二层开始的, 这样做是因为最后一层可以因为是没有子节点而看作是满足堆条件的for (int i = n / 2; i; i -- ) down(i);

