题目 综述 细节比较多
Codeclass Solution &#123;public: int mySqrt(int x) &#123; if(x==0||x==1)return x;//防止出现除0错误 int l=0,r=x; while(l&lt;r) &#123; int mid=l+1+(r-l)/2;//防止死循环 if(mid&gt;x/mid)r=mid-1;//这种判断的做法保证开平方的结果是向下取整的 else l=mid; &#125; return l; &#125;&#125;;
复杂度分析 时间复杂度：O(log(x)) 空间复杂度：O(1)

综述参考讲解视频链接
二分用于寻找性质的边界（第一个或者最后一个）
[l,r]都是闭区间，每次调整区间必须保证答案在区间内
考虑问题时考虑序列中第一个满足某个条件的数（r&#x3D;mid，右边界往左移找第一个），或者最后一个满足某个条件的数(l&#x3D;mid，左边界往右移找最后一个)
r&#x3D;mid找到的是第一个满足某个条件的数，l&#x3D;mid找到的是最后一个满足某个条件的数
整数二分算法模板 —— 模板题 AcWing 789. 数的范围bool check(int x) &#123;/* ... */&#125; // 检查x是否满足某种性质// 区间[l, r]被划分成[l, mid]和[mid + 1, r]时使用：int bsearch_1(int l, int r)&#123;    while (l &lt; r)    &#123;        int mid = l + r &gt;&gt; 1;        if (check(mid)) r = mid;    // check()判断mid是否满足性质        else l = mid + 1;    &#125;    return l;&#125;// 区间[l, r]被划分成[l, mid - 1]和[mid, r]时使用：int bsearch_2(int l, int r)&#123;    while (l &lt; r)    &#123;        int mid = l + r + 1 &gt;&gt; 1;        if (check(mid)) l = mid;        else r = mid - 1;    &#125;    return l;&#125;

浮点数二分算法模板 —— 模板题 AcWing 790. 数的三次方根bool check(double x) &#123;/* ... */&#125; // 检查x是否满足某种性质double bsearch_3(double l, double r)&#123;    const double eps = 1e-6;   // eps 表示精度，取决于题目对精度的要求    while (r - l &gt; eps)    &#123;        double mid = (l + r) / 2;        if (check(mid)) r = mid;        else l = mid;    &#125;    return l;&#125;

代码形式2（防止mid溢出的方法）：以下代码为这种类型二分模板int binarySearch(int A[],int left,int right,int x)&#123;	int mid;	while(left&lt;=right)&#123;		mid=(left+right)/2;//mid=left+(right-left)/2;防止mid溢出		if(A[mid]==x)return mid;		else if(A[mid]&gt;x)right=mid-1;		else left=mid+1;	&#125;	return -1;&#125;

题目 综述 回顾一下求最长回文子串的操作 回溯的思路参考一下这个题解（有一个优化是预处理字符串，快速得出某个子串是否为回文串） 注意代码中的注释
Codeclass Solution &#123;public: vector&lt;string&gt;ss; vector&lt;vector&lt;string&gt; &gt;res; vector&lt;vector&lt;string&gt;&gt; partition(string s) &#123; int n=s.size(); vector&lt;vector&lt;int&gt; &gt;dp(n+1,vector&lt;int&gt;(n+1,0)); for(int i=0;i&lt;n;i++)&#123; //求最长回文子串模板 help(i,i,s,dp); help(i,i+1,s,dp); &#125; //回溯求解 dfs(s,0,dp); return res; &#125; void help(int left,int right,string&amp; s,vector&lt;vector&lt;int&gt; &gt;&amp;dp)&#123; //中心扩散 while(left&gt;=0&amp;&amp;right&lt;s.size()&amp;&amp;s[left]==s[right])&#123; dp[left][right]=1; left--; right++; &#125; &#125; void dfs(string &amp;s,int left, vector&lt;vector&lt;int&gt; &gt;&amp;dp)&#123; if(s.size()==left)&#123; res.push_back(ss); return; &#125; for(int i=left;i&lt;s.size();i++)&#123; string temp=s.substr(left,i-left+1); if(!dp[left][i])&#123;//剪枝 continue;//不能写为return,常见错误 &#125; ss.push_back(temp); dfs(s,i+1,dp); ss.pop_back(); &#125; &#125;&#125;;
