题目 综述 KMP，解释见算法笔记455页 可从有限状态自动机的角度理解 next数组的含义以及优化
Codeclass Solution &#123;public: int strStr(string haystack, string needle) &#123; int m=haystack.size(); int n=needle.size(); if(n==0)return 0;//本题特判 vector&lt;int&gt;next=getNext(needle,n); int j=-1; for(int i=0;i&lt;m;i++)&#123; if(j!=-1&amp;&amp;haystack[i]!=needle[j+1])&#123; j=next[j]; &#125; if(haystack[i]==needle[j+1])&#123; j++; &#125; if(j==n-1)&#123;//匹配结束 return i-n+1;//i此时为haystack匹配串中的最后一位，i-n+1是匹配串的开始位置下标 //以下可用于统计匹配的次数 // ans++; // j=next[j];//让j回退到next[j]位置继续匹配 &#125; &#125; return -1; &#125;//求next数组 vector&lt;int&gt; getNext(string str,int len)&#123; vector&lt;int&gt; next(len,0); next[0]=-1; int j=-1; for(int i=1;i&lt;len;i++)&#123; if(j!=-1&amp;&amp;str[i]!=str[j+1])&#123; j=next[j]; &#125; if(str[i]==str[j+1])&#123; j++; &#125; //以下为next数组的优化，可快速回退，此时代码中的两个while均只执行一次，可以换为if if(j==-1||str[i+1]!=str[j+1])&#123; next[i]=j; &#125;else&#123; next[i]=next[j]; &#125; &#125; return next; &#125;&#125;;
复杂度分析 时间复杂度：O(m+n) 空间复杂度：O(n)

题目 综述 方法：使用 “快慢指针” 思想，找出循环：“快指针” 每次走两步，“慢指针” 每次走一步，当二者相等时，即为一个循环周期。此时，判断是不是因为 1 引起的循环，是的话就是快乐数，否则不是快乐数。 不是快乐数的数称为不快乐数（unhappy number），所有不快乐数的数位平方和计算，最後都会进入 4 → 16 → 37 → 58 → 89 → 145 → 42 → 20 → 4 的循环中；快乐数会进入1的循环
Codeclass Solution &#123;public: bool isHappy(int n) &#123; int fast=n; int slow=n; do&#123; slow=getNum(slow); fast=getNum(fast); fast=getNum(fast); &#125;while(fast!=slow); return fast==1; &#125; int getNum(int n)&#123; int ans=0; while(n&gt;0)&#123; ans+=(n%10)*(n%10); n/=10; &#125; return ans; &#125;&#125;;
复杂度分析

题目 综述 参考单词接龙题解
Codeclass Solution &#123;public: int openLock(vector&lt;string&gt;&amp; deadends, string target) &#123; unordered_set&lt;string&gt;deadendsSet(deadends.begin(),deadends.end());//字典存入set，加快查找速度 unordered_set&lt;string&gt;visit;//标记数组，标记是否已被访问 unordered_set&lt;string&gt;q1;//从前往后扩散时，每层保存的节点 unordered_set&lt;string&gt;q2;//从后往前扩散时，每层保存的节点 //注意点1：必须进行特判，因为从两端往中间扩散时，可能会存在这种情况： //target根本不在字典中，在往前扩散时，可能会存在公共交集的情况 if(deadendsSet.count(target)!=0||deadendsSet.count(&quot;0000&quot;))&#123; return -1; &#125; q1.insert(&quot;0000&quot;); q2.insert(target); int ans=-1; while(!q1.empty())&#123; ans++;//层数+1 unordered_set&lt;string&gt;temp; for(auto eachstr:q1)&#123;//一次遍历一层 visit.insert(eachstr);//注意点2：visit数组更新的位置 if(q2.count(eachstr)!=0)return ans;//存在交集，满足条件即可返回 for(int i=0;i&lt;4;i++)&#123; string str=eachstr;//不可少，保证每次都是基于eachstr的值修改 for(int j=0;j&lt;2;j++)&#123; str[i]=getChar(eachstr,i,j); if(deadendsSet.count(str)==0&amp;&amp;visit.count(str)==0)&#123; temp.insert(str); //和单源bfs不同，绝对不能在这里更新visit &#125; &#125; &#125; &#125; //正常情况下，下次访问q2 q1=q2; q2=temp; //优化：从集合元素少的扩散 if(q1.size()&gt;q2.size())&#123; swap(q1,q2); &#125; &#125; return -1; &#125; char getChar(string s,int i,int k)&#123; char c=s[i]; if(k==0)&#123;//增加 if(c==&#x27;9&#x27;)return &#x27;0&#x27;; else return c+1; &#125;else&#123; if(c==&#x27;0&#x27;)return &#x27;9&#x27;; else return c-1; &#125; &#125;&#125;;
复杂度分析

题目 综述 题解参考 涉及到的算法： 随机选择算法寻找第K大：参考 快排三路partation的变形（本题为了使用虚拟映射关系，需要把大的元素放mid左边，小的放右边）：参考【快排全解】笔记 虚拟映射关系（实现空间复杂度O(1)的关键）
Codeclass Solution &#123;public: void wiggleSort(vector&lt;int&gt;&amp; nums) &#123; int len=nums.size(); int k=(len+1)/2;//找第k大：中位数 int mid=findKthLargest(nums,k); #define A(i) nums[(1+2*(i)) % (len|1)]//虚拟映射关系 //快排三路归并的变形（大的元素放前面，小的放后面） //为了使用虚拟映射关系，需要把大的元素放mid左边，小的放右边（为什么这么做，不太理解） int lt=-1; int gt=len; int i=0; while(i&lt;gt)&#123; if(mid==A(i))&#123; ++i; &#125;else if(mid&lt;A(i))&#123; swap(A(i++),A(++lt)); &#125;else&#123; swap(A(i),A(--gt)); &#125; &#125; &#125; //第K大 int findKthLargest(vector&lt;int&gt;&amp; arr, int k) &#123; int nk=arr.size()-k+1;//第k个最大的元素相当于排序数组的第nk个元素 return randselect(arr,nk,0,arr.size()-1); &#125; int randselect(vector&lt;int&gt;&amp; arr,int nk,int left,int right)&#123; swap(arr[left],arr[rand()%(right-left+1)+left]); int temp=arr[left]; int i=left; int lt=left-1; int gt=right+1; while(i&lt;gt)&#123; if(temp==arr[i])&#123; ++i; &#125;else if(temp&gt;arr[i])&#123; swap(arr[i++],arr[++lt]); &#125;else&#123; swap(arr[i],arr[--gt]); &#125; &#125; //以上代码与快排写法完全一致 //下面代码是快速选择算法特有 /* 经过一次partition:划分得到的区间如下 区间：arr[low...lt] &lt; temp 区间：arr[gt...high] &gt; temp 区间：arr[lt+1...i) == temp 也即 arr[lt+1...gt-1] == temp */ //arr[lt+1]是整个区间的第lt-left+2个数:用al表示 //arr[gt-1]是整个区间的第gt-left个数:用ar表示 int al=lt-left+2; int ar=gt-left; if(nk&lt;al)&#123;//答案在区间[left,lt]中 return randselect(arr,nk,left,lt); &#125;else if(nk&gt;ar)&#123;//答案在区间[gt,right]中 return randselect(arr,nk-ar,gt,right); &#125;else &#123;//找到答案，即arr[lt+1...gt-1] 区间的任意一个数 return arr[lt+1]; &#125; &#125;&#125;;
复杂度分析 时间复杂度：O(n) 空间复杂度：O(1)

