综述int blockIndex = i / 3 * 3 + j / 3;
Codeclass Solution &#123;    public boolean isValidSudoku(char[][] board) &#123;        boolean[][] row = new boolean[9][9];        boolean[][] col = new boolean[9][9];        boolean[][] block = new boolean[9][9];        for (int i = 0; i &lt; 9; i++) &#123;            for (int j = 0; j &lt; 9; j++) &#123;                if(board[i][j]!=&#x27;.&#x27;)&#123;                    int num=board[i][j]-&#x27;1&#x27;;                    int blockIndex = i / 3 * 3 + j / 3;                    if(row[i][num]||col[j][num]||block[blockIndex][num])&#123;                        return false;                    &#125;else&#123;                        row[i][num]=true;                        col[j][num]=true;                        block[blockIndex][num]=true;                    &#125;                &#125;            &#125;        &#125;        return true;    &#125;&#125;

复杂度分析

题目 综述 可以看做小数指向大数的有向无环图 这道题算是dp的一种，一般从暴力的角度出发很容易想到dfs能直接获得每个点作为起始点得到的最长递增路径。这样的话，对着每个点做一次暴力dfs，就得到答案了，不过显然这样子会超时。 仔细想想实际上，dfs在经过每个点的时候，无论是不是从这个点开始的，都能得到从这个点出发的最长递增路径。于是“记忆化搜索”这个东西就来了。 可以利用二维数组记住每次dfs到的点的最长递增路径，这样下次递归到这个点的时候，就不用再接着递归了。 其中mem[x][y]记录的是从这个点出发的最长递增路径
Codeclass Solution &#123;public: int res=0; int step[2][4]=&#123;&#123;1,0,-1,0&#125;,&#123;0,1,0,-1&#125;&#125;; int longestIncreasingPath(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; int m=matrix.size(); if(m==0)return 0; int n=matrix[0].size(); vector&lt;vector&lt;int&gt;&gt;mem(m,vector&lt;int&gt;(n,0)); for(int i=0;i&lt;m;i++)&#123; for(int j=0;j&lt;n;j++)&#123; if(mem[i][j]==0)&#123; res=max(res,dfs(matrix,i,j,mem)); &#125; &#125; &#125; return res; &#125; int dfs(vector&lt;vector&lt;int&gt;&gt;&amp; matrix,int x,int y,vector&lt;vector&lt;int&gt;&gt;&amp; mem)&#123; //函数的作用：1.返回从当前点出发的最长递增路径。2.并把这个值存储在mem[x][y]中 if(mem[x][y]!=0)return mem[x][y];//已经计算过，直接返回 mem[x][y]=1;//初始默认值，结果一定大于等于1 for(int i=0;i&lt;4;i++)&#123; int tx=x+step[0][i]; int ty=y+step[1][i]; if(f(matrix,tx,ty,matrix[x][y]))&#123; mem[x][y]=max(mem[x][y],1+dfs(matrix,tx,ty,mem));//四个方向中的最大值是结果 &#125; &#125; return mem[x][y]; &#125; bool f(vector&lt;vector&lt;int&gt;&gt;&amp; matrix,int x,int y,int pre)&#123; int m=matrix.size(); int n=matrix[0].size(); //matrix[x][y]&lt;=pre不满足 if(x&lt;0||y&lt;0||x&gt;=m||y&gt;=n||matrix[x][y]&lt;=pre)return false; return true; &#125;&#125;;
复杂度分析 时间复杂度：O(mn) 空间复杂度：O(mn)

题目 综述 参考链接
Codeclass Solution &#123;public: int ans=0; int countPrimes(int n) &#123; vector&lt;int&gt;v(n,0); for(int i=2;i*i&lt;n;i++)&#123;//因子的对称性,sqrt(n)即为结束条件 if(v[i]==0)&#123;//v[i]为0代表素数 for(int j=i*i;j&lt;n;j+=i)&#123;//不用从2*i开始计算,存在大量的冗余 v[j]=1; &#125; &#125; &#125; for(int i=2;i&lt;n;i++)&#123; if(v[i]==0)ans++; &#125; return ans; &#125;&#125;;
复杂度分析 时间复杂度：O (N*loglogN)) 空间复杂度：O(n)

线段树的深度：O(logn) 线段树的节点个数：O(n) 线段树节点编号方式：线段树数组从下标1开始；节点x的左儿子编号：2x；右儿子编号2x+1 节点编号的最大值&lt;&#x3D;4n 原始数组使用都是按照下标左闭右闭
局限性：（update方法的局限性）
标记必须可以合并 可以快速更新区间信息
参考链接 递归线段树单点更新，区间查询struct Node &#123; int data; int l; int r;&#125;;Node tree[4005];int arr[1000];void build(int x, int l, int r) &#123; tree[x].l = l; tree[x].r = r; if (l == r) &#123; tree[x].data = arr[l]; return; &#125; int mid = (l + r) / 2; build(2 * x, l, mid); build(2 * x + 1, mid + 1, r); tree[x].data = tree[2 * x].data + tree[2 * x + 1].data;&#125;void change(int x, int index, int val) &#123; if (tree[x].l == tree[x].r &amp;&amp; index == tree[x].l) &#123; tree[x].data = val; arr[index] = val; return; &#125; int mid = (tree[x].l + tree[x].r) / 2; if (index &lt;= mid) &#123; change(2 * x, index, val); &#125; else &#123; change(2 * x + 1, index, val); &#125; tree[x].data = tree[2 * x].data + tree[2 * x + 1].data;&#125;int query(int x, int L, int R) &#123; if (tree[x].l == L &amp;&amp; tree[x].r == R) &#123; return tree[x].data; &#125; int mid = (tree[x].l + tree[x].r) / 2; if (R &lt;= mid) &#123; return query(2 * x, L, R); &#125; else if (L &gt;= mid + 1) &#123; return query(2 * x + 1, L, R); &#125; else &#123; return query(2 * x, L, mid) + query(2 * x + 1, mid + 1, R); &#125;&#125;
区间更新，区间查询不同的题只要改变update、push_up的代码即可解决 struct Node &#123; long l; long r; long data; long lazy_tag;&#125;;Node tree[400020];long arr[100005];void update(long x, long w) &#123; long len = tree[x].r - tree[x].l + 1; tree[x].data += w * len; if (tree[x].lazy_tag == -1)tree[x].lazy_tag = w; else tree[x].lazy_tag += w;&#125;void push_down(long x) &#123; update(2 * x, tree[x].lazy_tag); update(2 * x + 1, tree[x].lazy_tag); tree[x].lazy_tag = -1;&#125;void push_up(long x) &#123; tree[x].data = tree[2 * x].data + tree[2 * x + 1].data;&#125;void build(long x, long l, long r) &#123; tree[x].lazy_tag = -1; tree[x].l = l; tree[x].r = r; if (l == r) &#123; tree[x].data = arr[l]; return; &#125; long mid = (l + r) / 2; build(2 * x, l, mid); build(2 * x + 1, mid + 1, r); push_up(x);&#125;void change(long x, long w, long L, long R) &#123; if (tree[x].l == L &amp;&amp; tree[x].r == R) &#123; update(x, w); return; &#125; if (tree[x].lazy_tag != -1)push_down(x); long mid = (tree[x].l + tree[x].r) / 2; if (R &lt;= mid) &#123; change(2 * x, w, L, R); &#125; else if (L &gt;= mid + 1) &#123; change(2 * x + 1, w, L, R); &#125; else &#123; change(2 * x, w, L, mid); change(2 * x + 1, w, mid + 1, R); &#125; push_up(x);&#125;long query(long x, long L, long R) &#123; if (tree[x].l == L &amp;&amp; tree[x].r == R) &#123; return tree[x].data; &#125; if (tree[x].lazy_tag != -1)push_down(x); long mid = (tree[x].l + tree[x].r) / 2; if (R &lt;= mid) &#123; return query(2 * x, L, R); &#125; else if (L &gt;= mid + 1) &#123; return query(2 * x + 1, L, R); &#125; else &#123; return query(2 * x, L, mid) + query(2 * x + 1, mid + 1, R); &#125;&#125;
区间乘法&amp;区间加法&amp;区间修改需要设计两个懒节点，需要修改push_down的方法，要注意其中的优先级问题，先乘法后加法 #include &lt;iostream&gt;using namespace std;struct Node &#123; long l; long r; long data; //x-&gt;x*lazy_tag1+lazy_tag2 long lazy_tag1;//乘法标记，初始化为1 long lazy_tag2;//加法标记，初始化为0&#125;;Node tree[400020];long arr[100005];int p;//取模void update(long x, long w, int type) &#123; long len = tree[x].r - tree[x].l + 1; if (type == 1) &#123;//乘法 tree[x].data = tree[x].data * w % p; tree[x].lazy_tag1 = tree[x].lazy_tag1 * w % p; tree[x].lazy_tag2 = tree[x].lazy_tag2 * w % p; &#125; else &#123;//加法 tree[x].data += w * len; tree[x].lazy_tag2 += w; &#125;&#125;void push_down(long x) &#123; //优先级问题，先乘后加 update(2 * x, tree[x].lazy_tag1, 1);//乘法 update(2 * x, tree[x].lazy_tag2, 2);//加法 update(2 * x + 1, tree[x].lazy_tag1, 1);//乘法 update(2 * x + 1, tree[x].lazy_tag2, 2);//加法 tree[x].lazy_tag1 = 1; tree[x].lazy_tag2 = 0;&#125;void push_up(long x) &#123; tree[x].data = tree[2 * x].data + tree[2 * x + 1].data;&#125;void build(long x, long l, long r) &#123; //标记初始化 tree[x].lazy_tag1 = 1; tree[x].lazy_tag2 = 0; tree[x].l = l; tree[x].r = r; if (l == r) &#123; tree[x].data = arr[l]; return; &#125; long mid = (l + r) / 2; build(2 * x, l, mid); build(2 * x + 1, mid + 1, r); push_up(x);&#125;void change(long x, long w, long L, long R, int type) &#123; if (tree[x].l == L &amp;&amp; tree[x].r == R) &#123; update(x, w, type);//1. return; &#125; if (tree[x].lazy_tag1 != 1 || tree[x].lazy_tag2 != 0)push_down(x);//2. long mid = (tree[x].l + tree[x].r) / 2; if (R &lt;= mid) &#123; change(2 * x, w, L, R, type); &#125; else if (L &gt;= mid + 1) &#123; change(2 * x + 1, w, L, R, type); &#125; else &#123; change(2 * x, w, L, mid, type); change(2 * x + 1, w, mid + 1, R, type); &#125; push_up(x);//3.&#125;long query(long x, long L, long R) &#123; if (tree[x].l == L &amp;&amp; tree[x].r == R) &#123; return tree[x].data; &#125; if (tree[x].lazy_tag1 != 1 || tree[x].lazy_tag2 != 0)push_down(x);//1. long mid = (tree[x].l + tree[x].r) / 2; if (R &lt;= mid) &#123; return query(2 * x, L, R); &#125; else if (L &gt;= mid + 1) &#123; return query(2 * x + 1, L, R); &#125; else &#123; return query(2 * x, L, mid) + query(2 * x + 1, mid + 1, R);//2. &#125;&#125;int main() &#123; long n, m; while (cin &gt;&gt; n &gt;&gt; m &gt;&gt; p) &#123; for (long i = 0; i &lt; n; i++)cin &gt;&gt; arr[i]; build(1, 0, n - 1); for (long i = 0; i &lt; m; i++) &#123; long opt, x, y, k; cin &gt;&gt; opt; if (opt == 1) &#123; cin &gt;&gt; x &gt;&gt; y &gt;&gt; k; change(1, k, x - 1, y - 1, 1); &#125; else if (opt == 2) &#123; cin &gt;&gt; x &gt;&gt; y &gt;&gt; k; change(1, k, x - 1, y - 1, 2); &#125; else if (opt == 3) &#123; cin &gt;&gt; x &gt;&gt; y; cout &lt;&lt; query(1, x - 1, y - 1) % p &lt;&lt; endl; &#125; &#125; &#125; return 0;&#125;
zkw线段树单点更新，区间查询区间更新，区间查询复杂度分析 时间复杂度：O(logn) 空间复杂度：O(n)

综述
心里想象一个表达式树
后缀表达式是表达式树的后序遍历序列
中缀表达式是表达式树的中序遍历序列

Code后缀表达式求值
class Solution &#123;public:    stack&lt;int&gt;stk;    void eval(string s)    &#123;        int b=stk.top();stk.pop();        int a=stk.top();stk.pop();        if(s==&quot;+&quot;)stk.push(a+b);        else if(s==&quot;-&quot;)stk.push(a-b);        else if(s==&quot;*&quot;)stk.push(a*b);        else stk.push(a/b);    &#125;    int evalRPN(vector&lt;string&gt;&amp; tokens) &#123;        unordered_set&lt;string&gt; S&#123;&quot;+&quot;,&quot;-&quot;,&quot;*&quot;,&quot;/&quot;&#125;;        for(auto &amp;s :tokens)        &#123;            if(S.count(s))eval(s);            else stk.push(stoi(s));        &#125;        return stk.top();    &#125;&#125;;

中缀表达式求值
#include &lt;iostream&gt;#include &lt;cstring&gt;#include &lt;algorithm&gt;#include &lt;stack&gt;#include &lt;unordered_map&gt;using namespace std;stack&lt;int&gt; num;stack&lt;char&gt; op;void eval()&#123;    auto b = num.top(); num.pop();    auto a = num.top(); num.pop();    auto c = op.top(); op.pop();    int x;    if (c == &#x27;+&#x27;) x = a + b;    else if (c == &#x27;-&#x27;) x = a - b;    else if (c == &#x27;*&#x27;) x = a * b;    else x = a / b;    num.push(x);&#125;int main()&#123;    unordered_map&lt;char, int&gt; pr&#123;&#123;&#x27;+&#x27;, 1&#125;, &#123;&#x27;-&#x27;, 1&#125;, &#123;&#x27;*&#x27;, 2&#125;, &#123;&#x27;/&#x27;, 2&#125;&#125;;    string str;    cin &gt;&gt; str;    for (int i = 0; i &lt; str.size(); i ++ )    &#123;        auto c = str[i];        if (isdigit(c))        &#123;            int x = 0, j = i;            while (j &lt; str.size() &amp;&amp; isdigit(str[j]))                x = x * 10 + str[j ++ ] - &#x27;0&#x27;;            i = j - 1;            num.push(x);        &#125;        else if (c == &#x27;(&#x27;) op.push(c);        else if (c == &#x27;)&#x27;)        &#123;            while (op.top() != &#x27;(&#x27;) eval();            op.pop();        &#125;        else        &#123;            while (op.size() &amp;&amp; op.top() != &#x27;(&#x27; &amp;&amp; pr[op.top()] &gt;= pr[c]) eval();            op.push(c);        &#125;    &#125;    while (op.size()) eval();    cout &lt;&lt; num.top() &lt;&lt; endl;    return 0;&#125;

