题目
综述https://lyl0724.github.io/2020/01/25/1/
Code/** * Definition for singly-linked list. * struct ListNode &#123; *     int val; *     ListNode *next; *     ListNode(int x) : val(x), next(NULL) &#123;&#125; * &#125;; */class Solution &#123;public:    ListNode* swapPairs(ListNode* head) &#123;        if(head==NULL||head-&gt;next==NULL)return head;        ListNode* next=head-&gt;next;        head-&gt;next=swapPairs(next-&gt;next);        next-&gt;next=head;        return next;    &#125;&#125;;

迭代的思路参考K个一组反转链表的图解

/** * Definition for singly-linked list. * struct ListNode &#123; *     int val; *     ListNode *next; *     ListNode() : val(0), next(nullptr) &#123;&#125; *     ListNode(int x) : val(x), next(nullptr) &#123;&#125; *     ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public:    ListNode* swapPairs(ListNode* head) &#123;        if(!head||!head-&gt;next)return head;                ListNode *dummy=new ListNode(-1);        dummy-&gt;next=head;        ListNode* p=dummy;        while(1)        &#123;            ListNode *q=p;            for(int i=0;q&amp;&amp;i&lt;2;i++)q=q-&gt;next;            if(!q)break;            ListNode *pre=p-&gt;next,*cur=pre-&gt;next;            ListNode *t=cur-&gt;next;             cur-&gt;next=pre;//1            pre-&gt;next=t;//2            p-&gt;next=cur;//3            p=pre;//4        &#125;        return dummy-&gt;next;    &#125;&#125;;

