题目 综述 二叉搜索树的逆中序遍历 代码注释处的剪枝 因为k之前存在一个递归调用，所以必须要使用引用。因此重新写一个方法
Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: int ans=0; int kthLargest(TreeNode* root, int k) &#123; dfs(root,k); return ans; &#125; void dfs(TreeNode* root, int &amp;k) &#123; if(!root)return; dfs(root-&gt;right,k); k--; if(k==0) &#123; ans=root-&gt;val; return; &#125; dfs(root-&gt;left,k); &#125;&#125;;
