Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: // int maxDepth(TreeNode* root) &#123;//后序遍历返回最大值 // if(!root)&#123; // return 0; // &#125; // return max(maxDepth(root-&gt;left),maxDepth(root-&gt;right))+1; // &#125; int maxDepth(TreeNode* root) &#123;//层次遍历 queue&lt;TreeNode*&gt;q; if(!root)return 0; q.push(root); int ans=0; while(!q.empty())&#123; int n=q.size();//同一层次节点个数 for(int i=0;i&lt;n;i++)&#123; TreeNode* t=q.front(); q.pop(); if(t-&gt;left)q.push(t-&gt;left); if(t-&gt;right)q.push(t-&gt;right); &#125; ans++;//每一层遍历完+1 &#125; return ans; &#125;&#125;;
