题目 综述 详见注释中的注意点
Codeclass Solution &#123;public: int left_bound(vector&lt;int&gt;&amp; nums, int target)&#123; int high=nums.size();//注意点1 int low=0; int mid; while(low&lt;high)&#123;//注意点2，左闭右开 mid=low+(high-low) /2;//注意点3：防止溢出 if(nums[mid]&gt;target)high=mid;//注意点:4，左闭右开 else if(nums[mid]&lt;target)low=mid+1;//注意点5，除法向下取整，一般保证low=mid+1 else if(nums[mid]==target)high=mid;//注意点6 &#125; if(high==nums.size())return -1;//注意点7，high和low此时相等，取值范围是[0,nums.size()] return (nums[high]==target)?high:-1; &#125; int right_bound(vector&lt;int&gt;&amp; nums, int target)&#123; int high=nums.size(); int low=0; int mid; while(low&lt;high)&#123; mid=low+(high-low) /2; if(nums[mid]&lt;=target)low=mid+1; else high=mid; &#125; if(high==0)return -1; return (nums[high-1]==target)?high-1:-1;//注意点8，求右边界需要-1 &#125; vector&lt;int&gt; searchRange(vector&lt;int&gt;&amp; nums, int target) &#123; vector&lt;int&gt;ans; ans.push_back(left_bound(nums,target)); ans.push_back(right_bound(nums,target)); return ans; &#125;&#125;;
