题目
综述dp[i]表示以nums[i]结尾的最大子序和
在状态转移时同时维护一下子序列的第一个和最后一个元素即可
Codeclass Solution &#123;public:    int maxSubArray(vector&lt;int&gt;&amp; nums) &#123;        int n=nums.size();        vector&lt;int&gt;dp(n+1,0);        int res=-0x3f3f3f3f;        for(int i=0;i&lt;n;i++)        &#123;            if(dp[i]&gt;0)dp[i+1]=nums[i]+dp[i];            else dp[i+1]=nums[i];            res=max(res,dp[i+1]);        &#125;        return res;    &#125;&#125;;
#include&lt;bits/stdc++.h&gt;using namespace std;int main()&#123;	int a[100];	int n;	cin&gt;&gt;n;	for(int i=0;i&lt;n;i++)cin&gt;&gt;a[i];	int ans=a[0],num=a[0];//ans最终的和	int low=0,anslow=0;	int anshigh=0;	for(int i=1;i&lt;n;i++)&#123;		if(num&gt;0)&#123;			num+=a[i];		&#125;		else&#123;			num=a[i];			low=i;		&#125;		if(num&gt;ans)&#123;			ans=num;			anslow=low;			anshigh=i; 		&#125;	&#125;	cout&lt;&lt;ans&lt;&lt;&#x27; &#x27;&lt;&lt;anslow&lt;&lt;&#x27; &#x27;&lt;&lt;anshigh&lt;&lt;endl; 	return 0;&#125;

