题目 综述 定义四个边界（边界的值随着遍历逐渐变化） 四个方向依次遍历（1.遍历结束修改边界值；2.边界值修改之后判断是否满足条件）
Codeclass Solution &#123;public: vector&lt;int&gt; spiralOrder(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; vector&lt;int&gt;ans; if(matrix.size()==0||matrix[0].size()==0)return ans; int top=0; int bottom=matrix.size()-1; int left=0; int right=matrix[0].size()-1; while(1)&#123; //从左到右 for(int i=left;i&lt;=right;i++)ans.push_back(matrix[top][i]); top++; if(top&gt;bottom)break; //从上往下 for(int i=top;i&lt;=bottom;i++)ans.push_back(matrix[i][right]); right--; if(right&lt;left)break; //从右往左 for(int i=right;i&gt;=left;i--)ans.push_back(matrix[bottom][i]); bottom--; if(bottom&lt;top)break; //从下往上 for(int i=bottom;i&gt;=top;i--)ans.push_back(matrix[i][left]); left++; if(left&gt;right)break; &#125; return ans; &#125;&#125;;
复杂度分析

题目 综述看图写代码，熟记bfs代码
Codeclass Solution &#123;public: vector&lt;vector&lt;int&gt;&gt; updateMatrix(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; int m=matrix.size(); int n=matrix[0].size(); vector&lt;vector&lt;int&gt;&gt;ans=vector&lt;vector&lt;int&gt;&gt;(m,vector&lt;int&gt;(n,0)); vector&lt;vector&lt;int&gt;&gt;visit=vector&lt;vector&lt;int&gt;&gt;(m,vector&lt;int&gt;(n,0)); int dx[4]=&#123;1,-1,0,0&#125;,dy[4]=&#123;0,0,-1,1&#125;; queue&lt;pair&lt;int,int&gt;&gt; q; for(int i=0;i&lt;m;i++)&#123; for(int j=0;j&lt;n;j++)&#123; if(matrix[i][j]==0)&#123; q.push(&#123;i,j&#125;); visit[i][j] = 1; &#125; &#125; &#125; int cntd = 0; while (!q.empty()) &#123; int k = q.size(); for (int i = 0; i &lt; k; i++) &#123; pair&lt;int,int&gt; t=q.front(); q.pop(); int cx=t.first; int cy=t.second; if (matrix[cx][cy]== 1)ans[cx][cy]=cntd; for (int j = 0; j &lt; 4; j++) &#123; int tx = cx + dx[j]; int ty = cy + dy[j]; if (tx &gt;= 0 &amp;&amp; tx &lt; m &amp;&amp; ty &gt;= 0 &amp;&amp; ty &lt; n &amp;&amp; visit[tx][ty] == 0) &#123; q.push(&#123;tx,ty&#125;); visit[tx][ty] = 1; &#125; &#125; &#125; cntd++; &#125; return ans; &#125;&#125;;
复杂度分析

题目 综述 参考
Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) &#123;&#125; * ListNode(int x) : val(x), next(nullptr) &#123;&#125; * ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* reverseKGroup(ListNode* head, int k) &#123; ListNode *dummy=new ListNode(-1); dummy-&gt;next=head; ListNode* p=dummy; while(1) &#123; ListNode *q=p; for(int i=0;q&amp;&amp;i&lt;k;i++)q=q-&gt;next; if(!q)break; ListNode *pre=p-&gt;next,*cur=pre-&gt;next; for(int i=0;i&lt;k-1;i++) &#123; ListNode *t=cur-&gt;next; cur-&gt;next=pre; pre=cur; cur=t; &#125; auto t=p-&gt;next; t-&gt;next=cur; p-&gt;next=pre; p=t; &#125; return dummy-&gt;next; &#125;&#125;;
