题目 综述 单调栈模板题：求右边第一个xxx：倒序，左边第一个xxx：正序 先在nums[2]中跑一遍单调栈，并记录结果到哈希表，之后遍历nums1，求结果即可
Codeclass Solution &#123;public: vector&lt;int&gt; nextGreaterElement(vector&lt;int&gt;&amp; nums1, vector&lt;int&gt;&amp; nums2) &#123; int n2=nums2.size(); stack&lt;int&gt;st; unordered_map&lt;int,int&gt;h; for(int i=n2-1;i&gt;=0;i--) &#123; while(st.size()&amp;&amp;nums2[i]&gt;nums2[st.top()])st.pop(); if(st.size())h[nums2[i]]=st.top(); else h[nums2[i]]=-1; st.push(i); &#125; vector&lt;int&gt;ans; int n1=nums1.size(); for(int i=0;i&lt;n1;i++) &#123; int x=nums1[i]; if(h.count(x)&amp;&amp;h[x]!=-1)ans.push_back(nums2[h[x]]); else ans.push_back(-1); &#125; return ans; &#125;&#125;;
复杂度分析

题目 综述 使用取模模拟环状 单调栈模板题：求右边第一个xxx：倒序，左边第一个xxx：正序
Codeclass Solution &#123;public: vector&lt;int&gt; nextGreaterElements(vector&lt;int&gt;&amp; nums) &#123; stack&lt;int&gt;stk; int n=nums.size(); vector&lt;int&gt;ans(n); for(int i=2*n-1;i&gt;=0;i--) &#123; while(!stk.empty()&amp;&amp;nums[i%n]&gt;=nums[stk.top()]) stk.pop(); if(stk.size())ans[i%n]=nums[stk.top()]; else ans[i%n]=-1; stk.push(i%n); &#125; return ans; &#125;&#125;;
