Codeclass Solution &#123;public:    int maxProfit(vector&lt;int&gt;&amp; prices) &#123;        int n=prices.size();        vector&lt;vector&lt;vector&lt;int&gt;&gt;&gt;f(n,vector&lt;vector&lt;int&gt;&gt;(3,vector&lt;int&gt;(2,0)));        for(int k=1;k&lt;=2;k++)        &#123;            f[0][k][0]=0;            f[0][k][1]=-prices[0];        &#125;        for(int i=1;i&lt;n;i++)            for(int k=1;k&lt;=2;k++)            &#123;                f[i][k][0]=max(f[i-1][k][0],f[i-1][k][1]+prices[i]);                f[i][k][1]=max(f[i-1][k][1],f[i-1][k-1][0]-prices[i]);            &#125;        return f[n-1][2][0];    &#125;&#125;;
class Solution &#123;public:    int maxProfit(vector&lt;int&gt;&amp; prices) &#123;        int len=prices.size();        if(len==0)return 0;        int dp20=0;        int dp21=-prices[0];        int dp10=0;        int dp11=-prices[0];                for(int i=1;i&lt;len;i++)&#123;            dp20=max(dp20,dp21+prices[i]);            dp21=max(dp21,dp10-prices[i]);            dp10=max(dp10,dp11+prices[i]);            dp11=max(dp11,-prices[i]);        &#125;        return dp20;    &#125;&#125;;

