题目 综述 股票问题系列全解
注意初始化问题，以及空间优化 for(int i=1;i&lt;=k;i++)&#123; dp[0][i][1]=-prices[0]; dp[0][i][0]=0;&#125;
k&gt;len&#x2F;2时，转为k不限次数的情况
Codeclass Solution &#123;public: int maxProfit(int k, vector&lt;int&gt;&amp; prices) &#123; int len=prices.size(); if(len==0||k==0)return 0; if(k&gt;len/2)&#123; return maxProfit1(prices); &#125; // vector&lt;vector&lt;vector&lt;int&gt; &gt; &gt;dp(len,vector&lt;vector&lt;int&gt; &gt;(k+1,vector&lt;int&gt; (2,0))); // for(int i=1;i&lt;=k;i++)&#123; // dp[0][i][1]=-prices[0]; // dp[0][i][0]=0; // &#125; // for(int i=1;i&lt;len;i++)&#123; // for(int j=1;j&lt;=k;j++)&#123; // dp[i][j][0]=max(dp[i-1][j][0],dp[i-1][j][1]+prices[i]); // dp[i][j][1]=max(dp[i-1][j][1],dp[i-1][j-1][0]-prices[i]); // &#125; // &#125; // return dp[len-1][k][0]; vector&lt;vector&lt;int&gt; &gt;dp(k+1,vector&lt;int&gt;(2,0)); for(int i=1;i&lt;=k;i++)&#123; dp[i][0]=0; dp[i][1]=-prices[0]; &#125; for(int i=1;i&lt;len;i++)&#123; for(int j=1;j&lt;=k;j++)&#123; dp[j][0]=max(dp[j][0],dp[j][1]+prices[i]); dp[j][1]=max(dp[j][1],dp[j-1][0]-prices[i]); &#125; &#125; return dp[k][0]; &#125; int maxProfit1(vector&lt;int&gt;&amp; prices) &#123;//k不限次数的情况 int len=prices.size(); if(len==0)return 0; int un_hold=0; int hold=-prices[0]; for(int i=1;i&lt;len;i++)&#123; un_hold=max(un_hold,hold+prices[i]); hold=max(hold,un_hold-prices[i]); &#125; return un_hold; &#125;&#125;;
复杂度分析 时间复杂度：O(nk)
空间复杂度：O(k)

题目 综述 翻来翻去烦不烦？为什一定要插入前面或者后面啊，每一层的大小都知道了，直接在对应索引处赋值不行吗
Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode(int x) : val(x), left(NULL), right(NULL) &#123;&#125; * &#125;; */class Solution &#123;public: vector&lt;vector&lt;int&gt;&gt; zigzagLevelOrder(TreeNode* root) &#123; queue&lt;TreeNode*&gt;q; vector&lt;vector&lt;int&gt;&gt;ans; if(root)q.push(root); bool f=true; while(!q.empty()) &#123; int n=q.size(); vector&lt;int&gt;tmp(n,0); for(int i=0;i&lt;n;i++) &#123; auto t=q.front(); q.pop(); tmp[f?i:n-i-1]=t-&gt;val; if(t-&gt;left)q.push(t-&gt;left); if(t-&gt;right)q.push(t-&gt;right); &#125; ans.push_back(tmp); f=!f; &#125; return ans; &#125;&#125;;
