Codeclass Solution &#123;public: int col[20],dg[20],udg[20]; vector&lt;vector&lt;string&gt;&gt;ans; vector&lt;string&gt;g; vector&lt;vector&lt;string&gt;&gt; solveNQueens(int n) &#123; string t=&quot;&quot;; for(int i=0;i&lt;n;i++)t+=&quot;.&quot;; for(int i=0;i&lt;n;i++)g.push_back(t); dfs(0,n); return ans; &#125; void dfs(int u,int n) &#123; if(u==n) &#123; ans.push_back(g); return; &#125; for(int i=0;i&lt;n;i++) &#123; if(!col[i]&amp;&amp;!dg[u+i]&amp;&amp;!udg[u-i+n]) &#123; g[u][i]=&#x27;Q&#x27;; col[i]=1;dg[u+i]=1;udg[u-i+n]=1; dfs(u+1,n); col[i]=0;dg[u+i]=0;udg[u-i+n]=0; g[u][i]=&#x27;.&#x27;; &#125; &#125; &#125;&#125;;
