Codeclass Solution &#123;public: //反转一个单词 void reverse(string &amp;s,int l,int r) &#123; while(l&lt;=r) swap(s[l++],s[r--]); &#125; string reverseWords(string s) &#123; int n=s.size(); for(int i=0;i&lt;n;i++)//双指针模板，i为单词开始,j为单词结束 &#123; int j=i; while(j&lt;n&amp;&amp;s[j]!=&#x27; &#x27;)j++; reverse(s,i,j-1); i=j;//循环中还有一步i++,因此这里是i=j &#125; return s; &#125;&#125;;
