题目 综述 参考
去除图中的第四步就是本题的代码 Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) &#123;&#125; * ListNode(int x) : val(x), next(nullptr) &#123;&#125; * ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* reverseBetween(ListNode* head, int m, int n) &#123; ListNode *dummy=new ListNode(-1); dummy-&gt;next=head; ListNode *p=dummy; for(int i=0;i&lt;m-1;i++)p=p-&gt;next; ListNode *pre=p-&gt;next,*cur=pre-&gt;next; for(int i=0;i&lt;n-m;i++) &#123; ListNode *t=cur-&gt;next; cur-&gt;next=pre; pre=cur; cur=t; &#125; p-&gt;next-&gt;next=cur; p-&gt;next=pre; return dummy-&gt;next; &#125;&#125;;
