题目 综述 相比三数之和多加了一层遍历
Codeclass Solution &#123;public: vector&lt;vector&lt;int&gt;&gt; fourSum(vector&lt;int&gt;&amp; nums, int target) &#123; vector&lt;vector&lt;int&gt;&gt;ans; int n=nums.size(); if(n&lt;4)return ans; sort(nums.begin(),nums.end()); for(int a=0;a&lt;n-3;a++) &#123; if(a&gt;0&amp;&amp;nums[a]==nums[a-1])continue; for(int b=a+1;b&lt;n-2;b++) &#123; if(b&gt;a+1&amp;&amp;nums[b]==nums[b-1])continue; int c=b+1,d=n-1; while(c&lt;d) &#123; long sum=(long)nums[a]+(long)nums[b]+(long)nums[c]+(long)nums[d]; int left=nums[c],right=nums[d]; if(sum&gt;target) &#123; while(c&lt;d&amp;&amp;right==nums[d])d--; &#125; else if(sum&lt;target) &#123; while(c&lt;d&amp;&amp;left==nums[c])c++; &#125; else &#123; ans.push_back(&#123;nums[a],nums[b],nums[c],nums[d]&#125;); while(c&lt;d&amp;&amp;right==nums[d])d--; while(c&lt;d&amp;&amp;left==nums[c])c++; &#125; &#125; &#125; &#125; return ans; &#125;&#125;;
复杂度分析 时间复杂度：O(n^3) 空间复杂度：O(n^3)

