Codeclass Solution &#123;public: vector&lt;vector&lt;string&gt;&gt;res; vector&lt;string&gt;ans; vector&lt;string&gt;t; vector&lt;string&gt; restoreIpAddresses(string s) &#123; dfs(s,0,0); for(auto item:res)//处理答案 &#123; string str=&quot;&quot;; for(int i=0;i&lt;item.size();i++) &#123; if(i)str+=&quot;.&quot;; str+=item[i]; &#125; ans.push_back(str); &#125; return ans; &#125; void dfs(string &amp;s,int u,int x) &#123; if(x&gt;s.size())return;//x==s.size()不是结束条件 if(u==4)//形成4段则可以剪枝，从其中筛选出最终的答案 &#123; if(x==s.size())res.push_back(t);//只有x起始位置到最后才是最终的答案 return; &#125; for(int i=1;i&lt;=3;i++) &#123; if(x+i-1&gt;=s.size())break; string str=s.substr(x,i); if(stoi(str)&lt;=255&amp;&amp;!(str.size()&gt;1&amp;&amp;str[0]==&#x27;0&#x27;)) &#123; t.push_back(str); dfs(s,u+1,x+i); t.pop_back(); &#125; &#125; &#125;&#125;;
