题目
综述
观察规律可知，遍历方向由层数决定，而层数即为横纵坐标之和。
if,else不能颠倒(正方形情况)

Codeclass Solution &#123;public:    vector&lt;int&gt; findDiagonalOrder(vector&lt;vector&lt;int&gt;&gt;&amp; mat) &#123;        vector&lt;int&gt;ans;        int row=mat.size();        if (row==0)return ans;        int col=mat[0].size();        int r=0,c=0;        for(int i=0;i&lt;row*col;i++)        &#123;            ans.push_back(mat[r][c]);            //向上移动            if((r+c)%2==0)            &#123;                //前面两个if,else不能颠倒(正方形情况)                if(c==col-1)r++;                else if(r==0)c++;                else                &#123;                    c++;                    r--;                &#125;            &#125;            //向下移动            else            &#123;                //前面两个if,else不能颠倒(正方形情况)                if(r==row-1)c++;                else if(c==0)r++;                else                &#123;                    r++;                    c--;                &#125;            &#125;        &#125;        return ans;    &#125;&#125;;

复杂度分析

