题目 综述 数位dp 和windy数的去掉前导0的思路类似
Codeclass Solution &#123;public: int flag[10]=&#123;0&#125;; const int N=15; long long f[15][10]=&#123;0&#125;; void init()&#123; for(int i=0;i&lt;=9;i++)f[1][i]=flag[i]==1; for(int i=2;i&lt;N;i++)&#123; for(int j=0;j&lt;=9;j++)&#123; if(!flag[j])continue; for(int k=0;k&lt;=9;k++)&#123; if(!flag[k])continue; f[i][j]+=f[i-1][k]; &#125; &#125; &#125; &#125; int dp(int n)&#123; if(!n)return 0; vector&lt;int&gt;nums; while(n)nums.push_back(n%10),n/=10; int res=0; for(int i=nums.size()-1;i&gt;=0;i--)&#123; int x=nums[i]; for(int j=0;j&lt;x;j++)&#123; if(flag[j])&#123; res+=f[i+1][j]; &#125; &#125; if(!flag[x])break; if(!i)res++; &#125; for(int i=1;i&lt;nums.size();i++)&#123; for(int j=0;j&lt;=9;j++)&#123; if(flag[j])&#123; res+=f[i][j]; &#125; &#125; &#125; return res; &#125; int atMostNGivenDigitSet(vector&lt;string&gt;&amp; digits, int n) &#123; for(int i=0;i&lt;digits.size();i++)flag[digits[i][0]-&#x27;0&#x27;]=1; init(); return dp(n)-dp(0); &#125;&#125;;
复杂度分析

题目 综述 从左往右对于每一个当前数字-&gt;右边的比它大的要交换到前面来-&gt;如果有多个比它大的要找到最大的-&gt;如果最大的有多个，要拿最后一个和它交换 last[num]数组记录数字num出现的最后位置，初始化为-1，表示没有出现过;
Codeclass Solution &#123;public: int maximumSwap(int num) &#123; string str=to_string(num); int n=str.size(); int last[10];//记录每个数字出现的最后的位置，初始化为-1，表示没有出现过; memset(last,-1,sizeof last); for(int i=0;i&lt;n;i++) last[str[i]-&#x27;0&#x27;]=i; for(int i=0;i&lt;n;i++) for(int j=9;j&gt;str[i]-&#x27;0&#x27;;j--)//数字从大到小枚举 if(last[j]&gt;i) &#123; swap(str[i],str[last[j]]); return stoi(str); &#125; return num; &#125;&#125;;
复杂度分析 时间复杂度：O(n) 空间复杂度：O(1)

题目 综述 先回顾连续子数组的最大和 top,bottom双指针遍历所有可能的的两个“行对”，即子矩阵的上下两条边，这决定了矩阵的高 将top-bottom之间的每一列（求出每一列的累计的和）看成一维数组中的一项，在其中求最大子数组，即求出符合的子矩阵的宽
Codeclass Solution &#123;public: vector&lt;int&gt; getMaxMatrix(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) &#123; vector&lt;int&gt;ans(4,0); int n=matrix.size(), m=matrix[0].size(); vector&lt;vector&lt;int&gt;&gt;pre_sum(n+1,vector&lt;int&gt;(m,0)); for(int i=1;i&lt;=n;i++) for(int j=0;j&lt;m;j++) pre_sum[i][j]=pre_sum[i-1][j]+matrix[i-1][j]; int res=matrix[0][0];//初始化为左上角元素 for(int top=0;top&lt;n;top++) for(int bottom=top;bottom&lt;n;bottom++) &#123; vector&lt;int&gt;tmp; for(int k=0;k&lt;m;k++) tmp.push_back(pre_sum[bottom+1][k]-pre_sum[top][k]); int st=0,sum=tmp[0]; for(int i=1;i&lt;m;i++) &#123; if(sum&gt;0)sum+=tmp[i]; else &#123; sum=tmp[i]; st=i; &#125; if(sum&gt;res) &#123; res=sum; ans[0]=top; ans[1]=st; ans[2]=bottom; ans[3]=i; &#125; &#125; &#125; return ans; &#125;&#125;;
复杂度分析

题目 综述 纵向扫描 纵向扫描时，从前往后遍历所有字符串的每一列，比较相同列上的字符是否相同，如果相同则继续对下一列进行比较，如果不相同则当前列不再属于公共前缀，当前列之前的部分为最长公共前缀。
Codeclass Solution &#123;public: string longestCommonPrefix(vector&lt;string&gt;&amp; strs) &#123; int n=strs.size(); if(!n)return &quot;&quot;; int m=strs[0].size(); for(int i=0;i&lt;m;i++) for(int j=1;j&lt;n;j++) if(i==strs[j].size()||strs[j][i]!=strs[0][i]) return strs[0].substr(0,i); return strs[0]; &#125;&#125;;
复杂度分析

题目 综述 f数组表示以nums[i]结尾的LIS的组合的个数，初始化为1 若要LIS成立，我们只要考虑nums[j] &lt; nums[i]的情况，其他情况则不考虑 (1)当dp[j]+1 &gt; dp[i]时,意味着我们第一次找到这个组合 (2)当dp[j]+1 == dp[i]时,意味着我们不是第一次找到这个组合
Codeclass Solution &#123;public: int findNumberOfLIS(vector&lt;int&gt;&amp; nums) &#123; int n=nums.size(); vector&lt;int&gt;dp(n,1); vector&lt;int&gt;f(n,1); int len=1; for(int i=0;i&lt;n;i++) for(int j=0;j&lt;i;j++) if(nums[j]&lt;nums[i]) &#123; if(dp[j]+1&gt;dp[i]) &#123; dp[i]=dp[j]+1; f[i]=f[j]; &#125; else if(dp[i]==dp[j]+1) f[i]+=f[j]; len=max(len,dp[i]); &#125; int ans=0; for(int i=0;i&lt;n;i++) if(len==dp[i]) ans+=f[i]; return ans; &#125;&#125;;
复杂度分析

题目 综述 参考 注意和最长公共子序列的区别
Codeclass Solution &#123;public: int f[1010][1010]; int findLength(vector&lt;int&gt;&amp; A, vector&lt;int&gt;&amp; B) &#123; int res=0; for(int i=1;i&lt;=A.size();i++) for(int j=1;j&lt;=B.size();j++) &#123; if(A[i-1]==B[j-1]) f[i][j]=f[i-1][j-1]+1; else f[i][j]=0; res=max(res,f[i][j]); &#125; return res; &#125;&#125;;
