Code/** * Definition for a binary tree node. * struct TreeNode &#123; * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) &#123;&#125; * TreeNode(int x) : val(x), left(nullptr), right(nullptr) &#123;&#125; * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) &#123;&#125; * &#125;; */class Solution &#123;public: int sumNumbers(TreeNode* root) &#123; return dfs(root,0); &#125; int dfs(TreeNode* root,int pre_sum) &#123; if(!root)return 0; int t=pre_sum*10+root-&gt;val; if(!root-&gt;left&amp;&amp;!root-&gt;right)return t; return dfs(root-&gt;left,t)+dfs(root-&gt;right,t); &#125;&#125;;
