综述排序之后可以剪枝if(target&lt;candidates[i])break;
排序之后可以去重if(i&gt;st&amp;&amp;candidates[i]==candidates[i-1]) continue;

Codeclass Solution &#123;public:    vector&lt;vector&lt;int&gt;&gt;res;    vector&lt;int&gt;t;    vector&lt;vector&lt;int&gt;&gt; combinationSum2(vector&lt;int&gt;&amp; candidates, int target) &#123;        sort(candidates.begin(),candidates.end());        dfs(candidates,target,0);        return res;    &#125;    void dfs(vector&lt;int&gt;&amp; candidates, int target,int st)    &#123;        if(target==0)        &#123;            res.push_back(t);            return;        &#125;        for(int i=st;i&lt;candidates.size();i++)        &#123;            if(target&lt;candidates[i])break;//排序的剪枝            if(i&gt;st&amp;&amp;candidates[i]==candidates[i-1])//排序之后的去重                continue;            t.push_back(candidates[i]);            dfs(candidates,target-candidates[i],i+1);//注意这里是i+1            t.pop_back();        &#125;    &#125;&#125;;

