题目 综述 数组中的逆序对问题 从小到大排序 在merge时，左段数组L和右段数组R都是有序的了。当L[i]&lt;&#x3D;R[j]时，表示L[i]比R[j]~R[r]的元素都要小。因此res需加上j及以后元素的个数*L[i]，即res+&#x3D;(r-j+1) * L[i]。
Code# include &lt;bits/stdc++.h&gt;using namespace std;int q[100010], tmp[100010];long long merge_sort(int l, int r)&#123; if(l &gt;= r)return 0; int mid = l + (r - l) / 2; long long res=merge_sort(l, mid) + merge_sort(mid+1, r); int i=l, j=mid+1, k=0; while(i &lt;= mid &amp;&amp; j &lt;= r) &#123; if(q[i] &lt;= q[j]) &#123; res += q[i] * (r-j+1); tmp[k++] = q[i++]; &#125; else tmp[k++] = q[j++]; &#125; while(i &lt;= mid)tmp[k++] = q[i++]; while(j &lt;= r)tmp[k++] = q[j++]; for(int i = l, k=0; i &lt;= r; i++, k++)q[i] = tmp[k]; return res;&#125;int main()&#123; int n; cin &gt;&gt; n; for (int i=0; i &lt; n; i++) cin &gt;&gt; q[i]; cout &lt;&lt; merge_sort(0, n-1) &lt;&lt; endl; return 0;&#125;
