Code/** * Definition for singly-linked list. * struct ListNode &#123; * int val; * ListNode *next; * ListNode() : val(0), next(nullptr) &#123;&#125; * ListNode(int x) : val(x), next(nullptr) &#123;&#125; * ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public: ListNode* reverse(ListNode *head) &#123; if(!head||!head-&gt;next)return head; auto res=reverse(head-&gt;next); head-&gt;next-&gt;next=head; head-&gt;next=nullptr; return res; &#125; void reorderList(ListNode* head) &#123; if(!head||!head-&gt;next)return; ListNode *a=head,*b=head; //找到中点 while(a&amp;&amp;a-&gt;next) &#123; a=a-&gt;next-&gt;next; b=b-&gt;next; &#125; auto tb=b-&gt;next; b-&gt;next=nullptr; auto ta=head; //反转 tb=reverse(tb); //合并 ListNode* dummy=new ListNode(-1); ListNode *first=dummy; bool f=1; while(ta&amp;&amp;tb) &#123; if(f) &#123; first-&gt;next=ta; ta=ta-&gt;next; &#125; else &#123; first-&gt;next=tb; tb=tb-&gt;next; &#125; first=first-&gt;next; f=!f; &#125; if(!ta)first-&gt;next=tb; if(!tb) first-&gt;next=ta; head=dummy-&gt;next; &#125;&#125;;
