复杂度分析

只有加法不用去除前导0
高精度加法// C = A + B, A &gt;= 0, B &gt;= 0vector&lt;int&gt; add(vector&lt;int&gt; &amp;A, vector&lt;int&gt; &amp;B)&#123;    vector&lt;int&gt; C;    for(int i=0,t=0;i&lt;A.size()||i&lt;B.size()||t;i++)    &#123;        if(i&lt;A.size())t+=A[i];        if(i&lt;B.size())t+=B[i];        C.push_back(t%10);        t/=10;    &#125;    return C;&#125;

高精度减法// C = A - B, 满足A &gt;= B, A &gt;= 0, B &gt;= 0vector&lt;int&gt; sub(vector&lt;int&gt; &amp;A, vector&lt;int&gt; &amp;B)&#123;    vector&lt;int&gt; C;    for (int i = 0, t = 0; i &lt; A.size(); i ++ )    &#123;        t = A[i] - t;        if (i &lt; B.size()) t -= B[i];        C.push_back((t + 10) % 10);        if (t &lt; 0) t = 1;        else t = 0;    &#125;    while (C.size() &gt; 1 &amp;&amp; C.back() == 0) C.pop_back();    return C;&#125;

高精度乘法##大整数A乘小整数b

需要特判最后的进位,且t必须写进循环里
需要去除前导0vector&lt;int&gt; mul(vector&lt;int&gt;&amp; A,int b)&#123;    vector&lt;int&gt;C;    int t=0;    for(int i=0;i&lt;A.size()||t;i++)    &#123;        if(i&lt;A.size())t=A[i]*b+t;        C.push_back(t%10);        t/=10;    &#125;    while(C.size()&gt;1&amp;&amp;C.back()==0)C.pop_back();    return C;&#125;
##大整数乘大整数
从低位到高位计算，依次确定C数组的每一位
需要去除前导0vector&lt;int&gt;mul(vector&lt;int&gt; &amp;A,vector&lt;int&gt; &amp;B)&#123;    vector&lt;int&gt;C(A.size()+B.size(),0);    for(int i=0;i&lt;A.size();i++)        for(int j=0;j&lt;B.size();j++)        &#123;            int p1=i+j,p2=i+j+1;            int t=A[i]*B[j]+C[p1];            C[p1]=t%10; //该位置的值已经最终确定，取余即可            C[p2]+=t/10;//该位置的值还未确定，需要累加进位        &#125;    while(C.size()&gt;1&amp;&amp;C.back()==0)C.pop_back();    return C;&#125;

高精度除以低精度// A / b = C ... r, A &gt;= 0, b &gt; 0vector&lt;int&gt; div(vector&lt;int&gt; &amp;A, int b, int &amp;r)&#123;    vector&lt;int&gt; C;    r = 0;    for (int i = A.size() - 1; i &gt;= 0; i -- )    &#123;        r = r * 10 + A[i];        C.push_back(r / b);        r %= b;    &#125;    reverse(C.begin(), C.end());    while (C.size() &gt; 1 &amp;&amp; C.back() == 0) C.pop_back();    return C;&#125;

题目
综述Code/** * Definition for singly-linked list. * struct ListNode &#123; *     int val; *     ListNode *next; *     ListNode() : val(0), next(nullptr) &#123;&#125; *     ListNode(int x) : val(x), next(nullptr) &#123;&#125; *     ListNode(int x, ListNode *next) : val(x), next(next) &#123;&#125; * &#125;; */class Solution &#123;public:    ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) &#123;        if(!l1)return l2;        if(!l2)return l1;         ListNode *dummy=new ListNode(-1);        ListNode *p=dummy;        ListNode *a=l1,*b=l2;        while(l1&amp;&amp;l2)        &#123;            if(l1-&gt;val&lt;=l2-&gt;val)            &#123;                p-&gt;next=l1;                p=p-&gt;next;                l1=l1-&gt;next;            &#125;            else            &#123;                p-&gt;next=l2;                p=p-&gt;next;                l2=l2-&gt;next;            &#125;        &#125;        if(l1)p-&gt;next=l1;        else p-&gt;next=l2;        return dummy-&gt;next;    &#125;&#125;;
ListNode* merge(ListNode *a,ListNode *b)    &#123;        if(!a)return b;        if(!b)return a;        if(a-&gt;val&lt;=b-&gt;val)        &#123;            a-&gt;next=merge(a-&gt;next,b);            return a;        &#125;        else         &#123;            b-&gt;next=merge(a,b-&gt;next);            return b;        &#125;    &#125;

复杂度分析时间复杂度：O(n+m)
空间复杂度：O(1)
